\label{def:term}
\index{term}
Let $n \in \natural$.
An \textbf{$n$-ary\ $\Phi$-term} is defined by the following inductive clauses:
\begin{itemize}
\item $x_1, x_2, \dots, x_n$ are $n$-ary\ terms.
\item If $\phi \in \Phi_m$ and $t_1, \dots, t_m$ are $n$-ary\ terms, then $\phi
 (t_1, \dots, t_m)$ is an $n$-ary\ term.
\end{itemize}
A \textbf{$\Phi$-term} is an $n$-ary\ $\Phi$-term for some $n \in \natural$.

\index{var}
Let $t$ be an $n$-ary\ $\Phi$-term.
Then $\mathop{\rm{var}}(t)$ is the sequence of elements of $\{x_1, \dots, x_n\}$ given as
follows:
\begin{itemize}
\item $\mathop{\rm{var}}(x_i) = (x_i)$,
\item $\mathop{\rm{var}}(\phi  (t_1, \dots, t_n)) =
\mathop{\rm{var}}(t_1) \mathrel{++} \mathop{\rm{var}}(t_2) \mathrel{++} \dots \mathrel{++} \mathop{\rm{var}}(t_n)$,
\end{itemize}
where $\mathrel{++}$ is concatenation.

\index{supp}
Let $t$ be an $n$-ary\ $\Phi$-term.
Then $\mathop{\rm{supp}}(t)$, the \textbf{support of $t$}, is the subset of $\{x_1, \dots,
x_n\}$ given as follows:
\begin{itemize}
\item $\mathop{\rm{supp}}(x_i) = \{x_i\}$,
\item $\mathop{\rm{supp}}(\phi  (t_1, \dots, t_n)) =
\mathop{\rm{supp}}(t_1) \cup \mathop{\rm{supp}}(t_2) \cup \dots \cup \mathop{\rm{supp}}(t_n)$,
\end{itemize}

\label{def:sr_linterms}
\index{linear!term}\index{strongly regular!term}
An $n$-ary\ term $t$ is \textbf{linear} if $\mathop{\rm{label}}(t)$ is a bijection, and
\textbf{strongly regular} if $\mathop{\rm{label}}(t)$ is an identity.
\index{linear!equation}\index{strongly regular!equation}
An equation $(s,t)$ is \textbf{linear} if both $s$ and $t$ are linear, and
\textbf{strongly regular} if both $s$ and $t$ are strongly regular.

\index{presentation!of an algebraic theory}
A \textbf{presentation of a (one-sorted) algebraic theory} is 
\begin{itemize}
\item a signature $\Phi$,
\item a set $E$ of $\Phi$-equations.
\end{itemize}
\index{generating operation}
Elements of $\Phi_n$ are called ($n$-ary) \textbf{generating operations}.

\index{linear!presentation}
\index{strongly regular!presentation}
Let $P = (\Phi, E)$ be a presentation of an algebraic theory.
$P$ is \textbf{linear} if every equation in $E$ is linear, and
\textbf{strongly regular} if every equation in $E$ is strongly regular.

\index{algebra!for a signature}
Let $\Phi$ be a signature.
An \textbf{algebra} for $\Phi$ is
\begin{itemize}
\item a set $A$,
\item for each $n$-ary\ operation $\phi$, a map $\phi_A : A^n \to A$.
\index{primitive operation}
These are called the \textbf{primitive operations} of the algebra $A$.
\end{itemize}

\index{morphism!of algebras for a signature}
Let $\Phi$ be a signature, and $A$ and $B$ be $\Phi$-algebras.
A \textbf{morphism of $\Phi$-algebras} $f : A \to B$ is a map $f:A \to B$
which commutes with every primitive operation:
\[

	\xymatrix{
		A^n \ar[r]^-{f^n} \ar[d]_-{\phi_A}
		& B^n \ar[d]^-{\phi_B} \\
		A \ar[r]^-{f}
		& B
	}

\]
for every $n \in \natural$ and every $n$-ary\ primitive operation $\phi$.
If $P = (\Phi, E)$ is a presentation, then a \textbf{morphism of
$P$-algebras} is a morphism of $\Phi$-algebras.

\index{closure}
Let $\Phi$ be a signature and $E$ be a set of $\Phi$-equations.
The \textbf{closure} $\bar E$ of $E$ is the smallest equivalence relation on
$\mathop{\rm{term}} \Phi$ which contains $E$ and is closed under grafting of terms:
\begin{itemize}
\item if $(s,t) \in \bar E$, then $(s  (t_1, \dots, t_n), t  (t_1, \dots, t_n)) \in \bar E$ for all $t_1, \dots, t_n$.
\item if $(s_i, t_i) \in \bar E$ for $i = 1, \dots, n$, then $(t  (s_1,
\dots, s_n), t  (t_1, \dots, t_n)) \in \bar E$ for all $t$.
\end{itemize}

\index{morphism!of clones}
A \textbf{morphism} of clones $f: K \to K'$ is a map in $\ensuremath{\mbox{\upshape{\textbf{Set}}}}^\natural$
which commutes with the composition operations and $\delta$s.

\index{morphism!of algebras for a clone}
Let $A$ and $B$ be algebras for a clone $K$ in a finite product category $\ensuremath{\mathcal{C}}$
with specified finite powers.
A \textbf{morphism} of algebras $A \to B$ is a morphism $F : A \to B$ in \ensuremath{\mathcal{C}}\
such that the diagram
\[

	\xymatrix{
		A^n \ar[r]^-{F^n} \ar[d]_-{\hat k}
		& B^n \ar[d]^-{\hat k} \\
		A \ar[r]^-{F}
		& B
	}

\]
commutes for all $n \in \natural$ and all $k \in K_n$.

\index{Lawvere theory}
A \textbf{Lawvere theory} is a category $\mathcal{T}$ whose objects form a
denumerable set $\{\bf{0}, \bf{1}, \bf{2}, \dots \}$, such that $\bf{n}$ is the
$n$-th power of $\bf{1}$.
\index{morphism!of Lawvere theories}
A \textbf{morphism} of Lawvere theories $\mathcal{T} \to \mathcal{S}$ is an identity-on-objects
functor $\mathcal{T} \to \mathcal{S}$ which preserves projection maps.
The category of Lawvere theories and their morphisms is called $\ensuremath{\mbox{\upshape{\textbf{Law}}}}$.
\index{\ensuremath{\mbox{\upshape{\textbf{Law}}}}}
An \textbf{algebra} for $\mathcal{T}$ is a functor $F:\mathcal{T} \to \ensuremath{\mbox{\upshape{\textbf{Set}}}}$ which preserves
finite products.
\index{algebra!for a Lawvere theory}
A \textbf{morphism} of algebras is a natural transformation.
\index{morphism!of algebras for a Lawvere theory}
The \textbf{category of $\mathcal{T}$-algebras} is the full subcategory of $[\mathcal{T}, \ensuremath{\mbox{\upshape{\textbf{Set}}}}]$
whose objects are finite-product-preserving functors.

\label{def:monad_morphism}
\index{morphism!of monads}
Let $(T_1, \mu_1, \eta_1), (T_2, \mu_2, \eta_2)$ be monads on a category $\ensuremath{\mathcal{C}}$.
A \textbf{morphism of monads} $(T_1, \mu_1, \eta_1) \to (T_2, \mu_2, \eta_2)$
is a natural transformation $\alpha : T_1 \to T_2$ such that the diagrams
\begin{equation}
\label{eqn:monad_morph_mu}
\xymatrix{
	T_1^2 \ar[r]^{\mu_1} \ar[d]_{\alpha * \alpha} & T_1 \ar[d]^\alpha \\
	T_2^2 \ar[r]_{\mu_2} & T_2
}
\end{equation}
\begin{equation}
\label{eqn:monad_morph_eta}
\xymatrix{
	1 \ar[r]^{\eta_1} \ar[dr]_{\eta_2} & T_1 \ar[d]^{\alpha} \\
	& T_2
}
\end{equation}
commute.

\index{filtered!category}
A category $\ensuremath{\mathcal{C}}$ is \textbf{filtered} if every finite diagram in $\ensuremath{\mathcal{C}}$ admits a
cocone.

\index{finitary!functor}
A functor $F: \ensuremath{\mathcal{C}} \to \ensuremath{\mathcal{D}}$ is \textbf{finitary} if it preserves filtered
colimits.

\index{linear!clone}
\index{strongly regular!clone}
Let $K$ be a clone.
We say that $K$ is \textbf{strongly regular} (resp. \textbf{linear}) if
there exists a strongly regular (resp. linear) presentation $P$ such that
$K = K_{(\Phi, E)}$.

\label{def:umoncat}
\index{unbiased!monoidal category}
An \textbf{unbiased weak monoidal category} $(\ensuremath{\mathcal{C}}, \otimes, \gamma, \iota)$
consists of
\begin{itemize}
\item a category $\ensuremath{\mathcal{C}}$,
\item for each $n \in \natural$, a functor $\otimes_n : \ensuremath{\mathcal{C}}^n \to \ensuremath{\mathcal{C}}$ called \textbf{$n$-fold tensor} and written
\[
(a_1, \dots, a_n) \mapsto (a_1 \otimes \dots \otimes a_n)
\]
\item for each $n, k_1, \dots, k_n \in \natural$, a natural isomorphism
\[
\gamma : \otimes_n \circ (\otimes_{k_1} \times \dots \times \otimes_{k_n})
\longrightarrow \otimes_{\sum k_i}
\]
\item a natural isomorphism
\[
\iota: 1_A \to \otimes_1
\]
\end{itemize}
satisfying
\begin{itemize}
\item associativity: for any triple sequence $a^\bullet_{\bullet\bullet}$ of objects in $\ensuremath{\mathcal{C}}$, the
diagram
\[
\xymatrixrowsep{4pc}
\xymatrixcolsep{-10pc}
\xymatrix{
&(
((\otimes a_{1 1}^\bullet) \otimes \dots \otimes (\otimes a_{1 k_1}^\bullet))
\otimes \dots \otimes
((\otimes a_{n 1}^\bullet) \otimes \dots \otimes (\otimes a_{n k_n}^\bullet)))
\ar[dl] \ar[dr] \\
((\otimes a_{1 \bullet}^\bullet)
\otimes \dots \otimes
(\otimes a_{n \bullet}^\bullet))
\ar[dr]
& & ((\otimes a_{1 1}^\bullet) \otimes \dots \otimes
(\otimes a_{n k_n}^\bullet))
\ar[dl] \\
& (a_{1 1}^1 \otimes \dots \otimes a_{n k_n}^{m_{k_n}})
}
\]
commutes.
\item identity: for any $n \in \natural$ and any sequence $a_1, \dots, a_n$ of
objects in $\ensuremath{\mathcal{C}}$, the diagrams
\[
\xymatrixcolsep{4pc}
\xymatrixrowsep{4pc}
\xymatrix{
(a_1 \otimes \dots \otimes a_n) \ar[r]^{(\iota\otimes\dots\otimes\iota)}
\ar[dr]_1
& ((a_1) \otimes \dots \otimes (a_n)) \ar[d]^\gamma \\
& (a_1 \otimes \dots \otimes a_n)
}
\]
\[
\xymatrixcolsep{4pc}
\xymatrixrowsep{4pc}
\xymatrix{
(a_1 \otimes \dots \otimes a_n) \ar[r]^{\iota}
\ar[dr]_1
& ((a_1 \otimes \dots \otimes a_n)) \ar[d]^\gamma \\
& (a_1 \otimes \dots \otimes a_n)
}
\]
commute.
\end{itemize}

\index{multicategory!underlying multicategory of a monoidal category}
\index{unbiased!monoidal category!underlying multicategory}
Let $\ensuremath{\mathcal{C}}$ be a locally small unbiased weak monoidal category.
The \textbf{underlying multicategory} $\ensuremath{\mathcal{C}}'$ of $\ensuremath{\mathcal{C}}$ has
\begin{itemize}
\item objects: objects of $\ensuremath{\mathcal{C}}$;
\item arrows: $\ensuremath{\mathcal{C}}'(a_1, \dots, a_n; b) = \ensuremath{\mathcal{C}}(a_1\otimes\dots\otimes a_n, b)$;
\item composition given as follows: if $f_i \in \ensuremath{\mathcal{C}}'(a_1^i, \dots, a_{k_i}^i ;
b_i)$ for $i = 1, \dots, n$ and $g \in \ensuremath{\mathcal{C}}'(b_1, \dots, b_n; c)$, then we define
$g \circ (f_1, \dots, f_n)$ as
\[
\xymatrixnocompile{
\bigotimes_{i,j} a^i_j \ar[dd]_{f \circ (g_1, \dots, g_n)}
\ar[rr]^{\gamma \otimes \dots \otimes \gamma}
&& \bigotimes_i ( \bigotimes_j a^i_j ) \ar[dd]^{\bigotimes_i {f_i}} \\
\\
c
&& \bigotimes_i b_i \ar[ll]^g
}
\]
\end{itemize}

\index{algebra!for a plain multicategory}
Let $M$ and $\ensuremath{\mathcal{C}}$ be plain multicategories.
An \textbf{algebra} for $M$ in \ensuremath{\mathcal{C}}\ is a morphism of multicategories $M \to \ensuremath{\mathcal{C}}$.

\index{operad!plain!concrete description}
\label{lem:operad_description}
An operad $P$ can be given by the following data:
\begin{itemize}
\item A sequence $P_0, P_1, \dots$ of sets 
\item For all $n, k_1, \dots, k_n \in \natural$, a function $\circ: P_n
\times P_{k_1} \times \dots \times P_{k_n} \to P_{\sum k_i}$ 
\item An \textbf{identity element} $1 \in P_1$
\end{itemize}
satisfying the following axioms:
\begin{itemize}
\item \emph{Associativity:} $f \circ (g_\bullet \circ h_\bullet^\bullet) = (f \circ g_\bullet)
\circ h_\bullet^\bullet$ wherever this makes sense
\item \emph{Units:} $1 \circ f = f = f \circ (1, \dots, 1)$ for all f.
\end{itemize}

\label{ex:symmopd}
\index{\ensuremath{\mathcal{S}}!as a plain operad}
\index{operad of symmetries|see{\ensuremath{\mathcal{S}}}}
There is an operad $\ensuremath{\mathcal{S}}$ for which each $\ensuremath{\mathcal{S}}_n$ is the symmetric group
$S_n$.
Operadic composition is given as follows: if $\sigma \in S_n$, and $\tau_i \in
S_{k_i}$ for $i = 1, \dots, n$, then
\[
\sigma\circ(\tau_1, \dots, \tau_n) : \sum_{i = 1}^j k_i + m \mapsto 
\sum_{i: \sigma(i) < \sigma(j+1)} k_i + \tau_{j+1}(m)
\]
for all $j \in \{1, \dots, n\}$ and $m \in \{0, \dots, k_{j+1}-1\}$.
Informally, the inputs are divided into ``blocks'' of length $k_1, k_2, \dots,
k_n$, which are then permuted by $\sigma$: the elements of each block are then
permuted by the appropriate $\tau_i$.
For an example, see Figure \ref{fig:symm_comp}.
\begin{figure}[h]
\centerline{
	\epsfxsize=5in

	\epsfbox{symmcomp.eps}
}
\caption{Composition in the operad $\ensuremath{\mathcal{S}}$ of symmetries}
\label{fig:symm_comp}
\end{figure}

\index{\ensuremath{\mathcal{B}}}
\index{operad of braids|see{\ensuremath{\mathcal{B}}}}
There is an operad $\ensuremath{\mathcal{B}}$ for which each $\ensuremath{\mathcal{B}}_n$ is the Artin braid group
$B_n$.
Composition is analogous to that for $\ensuremath{\mathcal{S}}$: the inputs are divided into
blocks, which are braided, and then the elements of the blocks are braided.

\index{little $m$-discs operad}
\index{operad!little $m$-discs|see{little $m$-discs operad}}
Fix an $m \in \natural$.
There is an operad $LD$ for which each $LD_n$ is an embedding of $n$ copies of
the closed unit disc $D_m$ into $D_m$.
Composition is by gluing -- see Figure \ref{fig:little_discs}.
\begin{figure}[h]
\centerline{
	\epsfxsize=5in

	\epsfbox{little_discs.eps}
}
\caption{Composition in the little 2-discs operad}
\label{fig:little_discs}
\end{figure}

$LD$ is known as the \textbf{little $m$-discs operad}.

\index{morphism!of algebras for a plain operad}
Let $P$ be a plain operad, and $(A, (\hat{\phantom{\alpha}}))$ and $(B, (\check{\phantom{\alpha}}))$ be
algebras for $P$ in a multicategory $\ensuremath{\mathcal{C}}$.
A \textbf{morphism} of algebras is an arrow $F : A \to B$ in $\ensuremath{\mathcal{C}}$ such that,
for all $n \in \natural$, the diagram
\[
\xymatrix{
	P_n \ar[d]_{(\hat{\phantom{\alpha}})} \ar[r]^{(\check{\phantom{\alpha}})}
	& \mathop{\rm{End}}(B)_n \ar[d]^{-\circ(F,\dots,F)} \\
	\mathop{\rm{End}}(A)_n \ar[r]^-{F\circ -} & \ensuremath{\mathcal{C}}(A, \dots, A ; B)
}
\]
commutes.

\index{operad!symmetric}
A \textbf{symmetric operad} is a symmetric multicategory
with only one object.

\label{def:symmopd}
\xymatrixrowsep{5pc}
\xymatrixcolsep{6pc}
A \textbf{symmetric operad} is an operad $P$ together with an action of the
symmetric group $S_n$ on each $P_n$, which is compatible with the operadic
composition:
\[
\xymatrixrowsep{2pc}
\xymatrix{
	P_n \times \prod P_{k_i} \ar[r]^{(\sigma \cdot -) \times 1 \times \dots
		\times 1}
		\ar[d]_{1 \times \sigma_*} 
	& P_n \times \prod P_{k_i} \ar[dd]^{\circ} \\
	P_n \times \prod P_{\sigma k_i} \ar[d]_\circ
	\\
	P_{\sum k_i} \ar[r]^{(\sigma \circ (1, \dots, 1)) \cdot -}
	& P_{\sum k_i}
}
\xymatrix{
	P_n \times \prod P_{k_i}
		\ar[r]^{1 \times (\rho_1 \cdot -) \times \dots
			  \times (\rho_n \cdot -)}
		\ar[dd]_{\circ}
	& P_n \times \prod P_{k_i} \ar[dd]^{\circ} \\
	\\
	P_{\sum k_i} \ar[r]^{(1 \circ (\rho_1, \dots, \rho_n)) \cdot -}
	& P_{\sum k_i}
}
\]
\[
\xymatrix{
	P_n \ar@/u0.5cm/[r]^{1 \cdot -} \ar@/d0.5cm/[r]_1 & P_n
}
\]

\index{\ensuremath{\mathcal{S}}!as a symmetric operad}
The operad $\ensuremath{\mathcal{S}}$ of symmetric groups, as given in Example \ref{ex:symmopd}.
The action of $S_n$ on $\ensuremath{\mathcal{S}}_n$ is given by $\sigma \cdot \tau = \tau\sigma^{-1}$.

\label{ex:symmEnd}
\index{endomorphism operad!symmetric}
Let $\ensuremath{\mathcal{C}}$ be a symmetric multicategory, and $A \in \ensuremath{\mathcal{C}}$.
The \textbf{symmetric endomorphism operad} $\mathop{\rm{End}}(A)$ of $A$ is the full sub-(symmetric multicategory) of $\ensuremath{\mathcal{C}}$ whose only object is $A$.

\index{algebra!for a symmetric operad}
\index{morphism!of algebras for a symmetric operad}
Let $P$ be a symmetric operad.
An \textbf{algebra} for $P$ in a multicategory $\ensuremath{\mathcal{C}}$ is an object $A$ and a map $h : P \to \mathop{\rm{End}}(A)$ of symmetric operads.
A \textbf{morphism} $(A, h) \to (A', h')$ of $P$-algebras is an arrow $F: A
\to B$ in \ensuremath{\mathcal{C}}\ such that $h'F = Fh$.

\index{multicategory!finite product}
\label{dopdef}
A \textbf{finite product multicategory} is:
\begin{itemize}
\item A plain multicategory \ensuremath{\mathcal{C}};
\item for every morphism $f : {\underline{n}} \to {\underline{m}}$ in \ensuremath{\bbF}, and for all objects $C_1,
\dots, C_n, D \in \ensuremath{\mathcal{C}}$, a function $f\cdot - : \ensuremath{\mathcal{C}}(C_1, \dots, C_n;D) \to
\ensuremath{\mathcal{C}}(C_{f(1)}, \dots, C_{f(n)}; D)$
\end{itemize}
satisfying the following axioms:
\begin{itemize}
\item the \ensuremath{\bbF}-action is functorial: $f\cdot(g\cdot p) = (f\circ g)\cdot p$, and
${\rm id}_{{\underline{n}}}\cdot p = p$ wherever these equations make sense;
\item the \ensuremath{\bbF}-action and multicategorical composition interact by ``combing
out'':
\[
(f\cdot p)\circ(f_1\cdot p_1, \dots, f_n\cdot p_n) = (f\circ(f_1,\dots, f_n)) \cdot
(p\circ(p_{f(1)},\dots, p_{f(n)}))
\]
where $(f\circ(f_1,\dots, f_n))$ is given as follows:

Let $f:{\underline{n}} \to {\underline{m}}$, and $f_i:{{\underline{k}}}_i \to {{\underline{j}}_i}$ for $i = 1, \dots,
n$.
Then
\[
\begin{array}{rcccl}
f\circ(f_1, \dots, f_n) & : & {\underline{\sum k_i}} & \to & {\underline{\sum j_i}} \\
f\circ(f_1,\dots, f_n) & : & \left(\sum_{i=1}^{p-1} k_{f(i)}\right) + h
	& \mapsto & \left(\sum_{i=1}^{f(p)-1} j_i\right) + f_p(h)
\end{array}
\]
for all $p \in \{1, \dots, n\}$ and all $h \in \{1, \dots, k_{f(p)}\}$.
See Figure \ref{combfig}.
The small specks represent inputs to the arrow that are ignored.
\end{itemize}
\begin{figure}[h]
\centerline{

	\epsfysize=2in
	\epsfbox{combing.eps}
}
\caption{``Combing out'' the \ensuremath{\bbF}-action}
\label{combfig}
\end{figure}

\label{ex:fpEnd}
\index{endomorphism operad!finite product}
Let $\ensuremath{\mathcal{C}}$ be a finite product category, and $A$ be an object of $\ensuremath{\mathcal{C}}$.
Then there is a finite product operad\ $\mathop{\rm{End}}(A)$, the \textbf{endomorphism operad} of $A$,
where $\mathop{\rm{End}}(A)_n = \ensuremath{\mathcal{C}}(A^n,A)$, and $f\cdot p$ is $p$ composed with the
appropriate combination of projections to relabel its arguments by $f$.

\index{morphism!of finite product multicategories}
Let $M$, $N$ be finite product multicategories.
A \textbf{morphism} $F: M \to N$ consists of
\begin{itemize}
\item for each object $m \in M$, an object $Fm \in N$;
\item for each $n \in \natural$ and all $m_1, \dots, m_n, m \in M$, a map
\[
F_{m_1, \dots, m_n, m}: M(m_1, \dots m_n; m) \to N(Fm_1, \dots, Fm_n; Fm)
\]
commuting with the \ensuremath{\bbF}-action, the unit and composition.
\end{itemize}

\index{algebra!for a finite product multicategory}
Let $M$ be a finite product multicategory.
An \textbf{algebra} for $M$ in a finite product multicategory\ $\ensuremath{\mathcal{C}}$ is a map of finite product multicategories\ $M \to \ensuremath{\mathcal{C}}$.
An \textbf{algebra} for $M$ in a finite product category $\ensuremath{\mathcal{C}}$ is a map of
finite product multicategories\ from $M$ to the underlying finite product multicategory\ of \ensuremath{\mathcal{C}}.
Finite product multicategories\ and their morphisms form a category called {\ensuremath{\mbox{\upshape{\textbf{FP-Multicat}}}}}. \index{{\ensuremath{\mbox{\upshape{\textbf{FP-Operad}}}}}}

\index{algebra!for a ring}
The algebras in $\ensuremath{\mathcal{C}}$ for the operad described in Example \ref{ex:Ralg_fp} are
associative $R$-algebras in $\ensuremath{\mathcal{C}}$.

\index{commutative monoids}
The algebras for the operad described in Example \ref{ex:comm_monoid_fp} are
commutative monoid objects in $\ensuremath{\mathcal{C}}$.

\label{thm:dop-clone alg}
Let $P$ be a finite product operad.
Then $\ensuremath{\mbox{\upshape{\textbf{Alg$(P)$}}}} \cong \ensuremath{\mbox{\upshape{\textbf{Alg$(K_P)$}}}}$.

\label{lem:frees_exist}
Let $\Csmall$ and $\Dsmall$ be small finite-product categories, let $\ensuremath{\mathcal{C}}$ be
cartesian closed and have all small colimits, and let $Q: \Csmall \to \Dsmall$
preserve finite products.
Then the adjunction
\[

	\xymatrix{
		[\Dsmall,\ensuremath{\mathcal{C}}] \ar@<1ex>[r]^-{Q_!}_-{\bot}
		& [\Csmall,\ensuremath{\mathcal{C}}] \ar@<1.1ex>[l]^-{Q^*}
	}
,
\]
where $Q^*$ is composition with $Q$ and $Q_! = \mathop{\rm{Lan}}_Q$, restricts to an
adjunction
\[

	\xymatrix{
		\ensuremath{\mbox{\upshape{\textbf{FP}}}}(\Dsmall,\ensuremath{\mathcal{C}}) \ar@<1ex>[r]^-{Q_!}_-{\bot}
		& \ensuremath{\mbox{\upshape{\textbf{FP}}}}(\Csmall,\ensuremath{\mathcal{C}}) \ar@<1.1ex>[l]^-{Q^*}
	}
,
\]
\label{lem:leftadj}

\label{lem:monadj}
Let $S$ be a set, whose elements we will call \textbf{sorts}.
Let $T$ and $T'$ be $S$-sorted finite product theories, such that $T'$ is a
subcategory of $T$ and the inclusion of $T'$ into $T$ preserves finite
products.
Let $\ensuremath{\mbox{\upshape{\textbf{Alg$(T)$}}}}$ be the category of $T$-algebras and morphisms in some finite
product category $\ensuremath{\mathcal{C}}$, and $\ensuremath{\mbox{\upshape{\textbf{Alg$(T')$}}}}$ be the category of $T'$-algebras and
morphisms in $\ensuremath{\mathcal{C}}$.
Then the free/forgetful adjunction
\[ 

	\xymatrix{
		\ensuremath{\mbox{\upshape{\textbf{Alg$(T')$}}}} \ar@<1ex>[r]^-{F}_-{\bot}
		& \ensuremath{\mbox{\upshape{\textbf{Alg$(T)$}}}} \ar@<1.1ex>[l]^-{U}
	}

\]
is monadic, provided the left adjoint $F$ exists.

\def\prod # s_i1{\prod #1 s_i}
\def\prod # r_j1{\prod #1 r_j}
\def\prod #_{s_i}1{\prod #1_{s_i}}
\def\prod #_{r_j}1{\prod #1_{r_j}}
We will make use of Beck's theorem to prove monadicity: precisely, we shall
make use of the version in \cite{catwork} VI.7.1, which states that $U$ is
monadic if it has a left adjoint and it strictly creates coequalizers for
$U$-absolute coequalizer pairs.
Recall that a functor $G: \ensuremath{\mathcal{C}} \to \ensuremath{\mathcal{D}}$ \textbf{strictly creates coequalizers}
for a diagram $ \xymatrix{A \ar@<0.5ex>[r]^-{f} \ar@<-0.5ex>[r]_-{g} & B} $ in $\ensuremath{\mathcal{C}}$ if, for every coequalizer $e: GB
\to E$ of $Gf$ and $Gg$ in $\ensuremath{\mathcal{D}}$, there are a unique object $E'$ in $\ensuremath{\mathcal{C}}$ and a
unique arrow $e' : B \to E'$ such that $GE' = E$ and $Ge' = e$, and moreover
that $e'$ is a coequalizer of $ \xymatrix{A \ar@<0.5ex>[r]^-{f} \ar@<-0.5ex>[r]_-{g} & B} $.

Let $ \xymatrix{A \ar@<0.5ex>[r]^-{f} \ar@<-0.5ex>[r]_-{g} & B} $ be a $U$-absolute coequalizer pair in $\ensuremath{\mbox{\upshape{\textbf{Alg$(T)$}}}}$,
and $e: U B \to E$ be the coequalizer of $ \xymatrix{UA \ar@<0.5ex>[r]^-{Uf} \ar@<-0.5ex>[r]_-{Ug} & UB} $.
We wish to extend $E$ to a functor $E': T \to \ensuremath{\mathcal{C}}$.
Define $E'$ to be equal to $E$ on objects.
On arrows, we shall define $E'$ using the universal property of $E$ and the
$U$-absolute property of $ \xymatrix{A \ar@<0.5ex>[r]^-{f} \ar@<-0.5ex>[r]_-{g} & B} $.

For each arrow $\phi : s_1 \times \dots \times s_n \to r_1 \times \dots
\times r_m$ in $T$ (where $s_i, r_j \in S$),
consider the diagram
\begin{equation}
\label{eqn:coeq}
\xymatrixrowsep{4pc}
\xymatrixcolsep{4pc}
\xymatrixnocompile{
	\prod U A s_i \ar@<0.5ex>[r]^-{\prod U f_{s_i}} \ar@<-0.5ex>[r]_-{\prod Ug_{s_i}} \ar[d]_{A\phi}
	& \prod U B s_i \ar[r]^{\prod e_{s_i}} \ar[d]_{B\phi}
	& \prod E s_i \ar@{..>}[d]^{E'\phi}\\
	\prod U A r_j \ar@<0.5ex>[r]^-{\prod f_{r_j}} \ar@<-0.5ex>[r]_-{\prod g_{r_j}}
	& \prod U B r_j \ar[r]^{\prod e_{r_j}}
	& \prod E r_j
}
\end{equation}
in $\ensuremath{\mathcal{C}}$, where $e: UB \to E$ is a coequalizer for $ \xymatrix{UA \ar@<0.5ex>[r]^-{Uf} \ar@<-0.5ex>[r]_-{Ug} & UB} $.

Since $ \xymatrix{A \ar@<0.5ex>[r]^-{f} \ar@<-0.5ex>[r]_-{g} & B} $ is a $U$-absolute coequalizer pair, $\prod e_{s_i}
: \prod UB s_i \to \prod E s_i$ is a coequalizer.
Since $f$ and $g$ are $T$-homomorphisms, (\ref{eqn:coeq}) serially commutes, so
$(\prod e_{r_j})\phi$ factors uniquely through $\prod e_{s_i}$.
Define $E'\phi$ to be this map, as shown (and note that $E'\phi = E\phi$ if
$\phi$ is in $T'$).
This definition straightforwardly makes $E'$ into a functor $T \to \ensuremath{\mathcal{C}}$.
Since $E$ is a $T'$-algebra, and products in $T$ are the same as products in
$T'$, we may deduce that $E': T\to C$ preserves finite products, and thus is
a $T$-algebra.
Clearly, $E'$ is the unique extension of $E$ to a $T$-algebra such that $e$ is
a $T$-algebra morphism.
It remains to show that $e$ is a coequalizer map for $ \xymatrix{A \ar@<0.5ex>[r]^-{f} \ar@<-0.5ex>[r]_-{g} & B} $ in
$\ensuremath{\mbox{\upshape{\textbf{Alg$(T)$}}}}$.

Suppose $
	\xymatrix{A \ar@<0.5ex>[r]^-{f} \ar@<-0.5ex>[r]_-{g} & B \ar[r]^-{d} & D }
$ is a fork in $\ensuremath{\mbox{\upshape{\textbf{Alg$(T)$}}}}$.
Then $
	\xymatrix{UA \ar@<0.5ex>[r]^-{Uf} \ar@<-0.5ex>[r]_-{Ug} & UB \ar[r]^-{Ud} & UD }
$ is a fork in $\ensuremath{\mbox{\upshape{\textbf{Alg$(T')$}}}}$, so $Ud$
factors through $e$; say $Ud = he$.
We must show that $h$ is a $T$-homomorphism.
As before, take $\phi : s_1 \times \dots \times s_n \to r_1 \times \dots \times
r_m$ in $T$, and consider the diagram
\begin{equation}
\xymatrixcolsep{4pc}
\xymatrixnocompile{
	\prod U A s_i \ar@<0.5ex>[r]^-{\prod U f_{s_i}} \ar@<-0.5ex>[r]_-{\prod U g_{s_i}} \ar[dd]_{A\phi}
	& \prod U B s_i \ar[r]^{\prod e_{s_i}}
		\ar[dd]_{B\phi} \ar[dr]_{\prod Ud_{s_i}}
	& \prod E' s_i \ar@/r1cm/[dd]^{E'\phi} \ar@{..>}[d]_{\prod h_{s_i}} \\
	& & \prod U D s_i \ar@/r1cm/[dd]^{D\phi} \\
	\prod U A r_j \ar@<0.5ex>[r]^-{\prod f_{r_j}} \ar@<-0.5ex>[r]_-{\prod g_{r_j}}
	& \prod U B r_j \ar[r]^{\prod e_{r_j}} \ar[dr]_{\prod Ud_{r_j}}
	& \prod E' r_j \ar@{..>}[d]_{\prod h_{r_j}} \\
	& & \prod D r_j
}
\end{equation}

We must show that the curved square on the far right commutes.
Now $(D\phi) \circ (\prod d_{s_i}) = (D\phi) \circ (\prod h_{s_i}) \circ (\prod e_{s_i})$, and $(\prod Ud_{r_j})\circ(UB\phi) = h\circ e\circ(UB\phi) = h \circ
(E\phi) \circ (\prod e_{s_i})$, since $e$ is a $T$-algebra homomorphism.
But $(\prod Ud_{r_j})\circ \phi = \phi \circ (\prod d_i)$, so $D\phi \circ
(\prod h_{s_i}) \circ (\prod e_{s_i}) = h \circ (E\phi) \circ (\prod e_{s_i})$.
And $\prod e_{s_i}$ is (regular) epic, so $h \circ (E\phi) = (D\phi) \circ
(\prod h_{s_i})$.

So $h$ is a $T$-algebra homomorphism.
Hence $U$ strictly creates coequalizers for $U$-absolute coequalizer pairs,
and hence is monadic.

\label{thm:opd monadic over setN}
\index{\ensuremath{\mbox{\upshape{\textbf{Operad}}}}!monadicity over $\ensuremath{\mbox{\upshape{\textbf{Set}}}}^\natural$}
All the adjunctions in diagram \ref{eqn:adjs}, namely ${\ensuremath{F_{\rm fp}^{\Sigma}}} \dashv {\ensuremath{U^{\rm fp}_{\Sigma}}}, {\ensuremath{F_{\rm fp}^{\rm pl}}} \dashv {\ensuremath{U^{\rm fp}_{\rm pl}}}, {\ensuremath{F_{\rm fp}}} \dashv
{\ensuremath{U^{\rm fp}}}, {\ensuremath{F_{\Sigma}^{\rm pl}}} \dashv {\ensuremath{U^{\Sigma}_{\rm pl}}}, {\ensuremath{F_{\Sigma}}} \dashv {\ensuremath{U^{\Sigma}}}$ and ${\ensuremath{F_{\rm pl}}} \dashv {\ensuremath{U^{\rm pl}}}$, are
monadic.

\label{def:srterm}
\index{tree!strongly regular}
\index{strongly regular!tree|see{tree, strongly regular}}
Let $\Phi$ be a signature.
An \textbf{$n$-ary\ strongly regular tree labelled by $\Phi$} is an element of
the set $\mathop{\mbox{tr}}_n \Phi$, which is recursively defined as follows:
\begin{itemize}
\item $|$ is an element of $\mathop{\mbox{tr}}_1 \Phi$.
\item If $\phi \in \Phi_n$, and $\tau_1 \in \mathop{\mbox{tr}}_{k_1} \Phi, \dots, \tau_n \in
\mathop{\mbox{tr}}_{k_n} \Phi$, then $\phi \circ(\tau_1, \dots, \tau_n) \in
\mathop{\mbox{tr}}_{\sum k_i} \Phi$.
\end{itemize}

We proceed by checking the triangle identities.
We require to show that
\begin{eqnarray}
\label{eqn:triarrFp}
\xymatrix{
	{\ensuremath{F_{\rm pl}}} \ar[r]^{{\ensuremath{F_{\rm pl}}}\eta} \ar[dr]_{1_{{\ensuremath{F_{\rm pl}}}}}
	& {\ensuremath{F_{\rm pl}}}{\ensuremath{U^{\rm pl}}}{\ensuremath{F_{\rm pl}}} \ar[d]^{\epsilon{\ensuremath{F_{\rm pl}}}} \\
	& {\ensuremath{F_{\rm pl}}}
} \\
\label{eqn:triarrUp}
\xymatrix{
	{\ensuremath{U^{\rm pl}}} \ar[r]^{\eta{\ensuremath{U^{\rm pl}}}} \ar[dr]_{1_{{\ensuremath{U^{\rm pl}}}}}
	& {\ensuremath{U^{\rm pl}}}{\ensuremath{F_{\rm pl}}}{\ensuremath{U^{\rm pl}}} \ar[d]^{{\ensuremath{U^{\rm pl}}}\epsilon} \\
	& {\ensuremath{U^{\rm pl}}}
}
\end{eqnarray}
commute.
For (\ref{eqn:triarrFp}), we proceed by induction on trees.
We shall suppress all subscripts on natural transformations in the interest of
legibility.
For the base case:
\begin{eqnarray*}
\epsilon{\ensuremath{F_{\rm pl}}} ( {\ensuremath{F_{\rm pl}}}\eta (|)) & = & \epsilon{\ensuremath{F_{\rm pl}}} (| \circ(|)) \\
	& = & | \circ(\epsilon(|)) \\
	& = & | \\
	& = & 1_{\ensuremath{F_{\rm pl}}}(|).
\end{eqnarray*}
For the inductive step, let $\Phi$ be a signature, $\phi$ be an $n$-ary\ element of $\Phi$, and $\tau_1, \dots, \tau_n$ be trees labelled by $\Phi$.
Then:
\begin{eqnarray*}
(\epsilon{\ensuremath{F_{\rm pl}}}) ( ({\ensuremath{F_{\rm pl}}}\eta) (\phi \circ(\tau_1, \dots, \tau_n) ))
	& = & \epsilon{\ensuremath{F_{\rm pl}}} (\phi \circ(\tau_1, \dots, \tau_n)\circ(|, \dots, |)) \\
	& = & \phi \circ(\tau_1, \dots, \tau_n)
		\circ((\epsilon{\ensuremath{F_{\rm pl}}})(|), \dots, (\epsilon{\ensuremath{F_{\rm pl}}})(|)) \\
	& = & \phi \circ(\tau_1, \dots, \tau_n) \\
	& = & 1_{\ensuremath{F_{\rm pl}}}(\phi \circ(\tau_1, \dots, \tau_n))
\end{eqnarray*}

Hence $\epsilon{\ensuremath{F_{\rm pl}}} \circ {\ensuremath{F_{\rm pl}}}\eta = 1{\ensuremath{F_{\rm pl}}}$, as required.

For (\ref{eqn:triarrUp}), let $P$ be a plain operad, and let $p$ be an $n$-ary\
arrow in $P$.
\begin{eqnarray*}
({\ensuremath{U^{\rm pl}}}\epsilon) ((\eta{\ensuremath{U^{\rm pl}}}) (p)) & = & {\ensuremath{U^{\rm pl}}}\epsilon (p\circ(|, \dots, |)) \\
	& = & p\circ(({\ensuremath{U^{\rm pl}}}\epsilon)(|), \dots, ({\ensuremath{U^{\rm pl}}}\epsilon)(|)) \\
	& = & p\circ(1, \dots, 1) \\
	& = & p \\
	& = & 1_{\ensuremath{U^{\rm pl}}}(p)
\end{eqnarray*}
So ${\ensuremath{U^{\rm pl}}}\epsilon \circ \eta{\ensuremath{U^{\rm pl}}} = 1_{\ensuremath{U^{\rm pl}}}$, as required.

\label{lem:Stimes=Fsigp}
$(\ensuremath{\mathcal{S}} \times -) $ is left adjoint to ${\ensuremath{U^{\Sigma}_{\rm pl}}}$.
The unit of the adjunction is given by 
\begin{eqnarray*}
\eta: 1 & \to & {\ensuremath{U^{\Sigma}_{\rm pl}}} (\ensuremath{\mathcal{S}} \times -) \\
\eta_P: p & \mapsto & (1, p),
\end{eqnarray*}
and the counit is given by 
\begin{eqnarray*}
\epsilon : (\ensuremath{\mathcal{S}} \times -) {\ensuremath{U^{\Sigma}_{\rm pl}}} & \to & 1 \\
\epsilon_P : (\sigma, p) & \mapsto & \sigma \cdot p.
\end{eqnarray*}

\label{def:permtree}
\index{tree!permuted}
Let $\Phi$ be a signature.
An \textbf{$n$-ary\ permuted tree labelled by $\Phi$} is an element of $({\ensuremath{F_{\Sigma}^{\rm pl}}}
{\ensuremath{F_{\rm pl}}} \Phi)_n = ({\ensuremath{F_{\Sigma}}} \Phi)_n$.
\index{tree!finite product}
An \textbf{$n$-ary\ finite product tree labelled by $\Phi$} is an element of
$({\ensuremath{F_{\rm fp}}} \Phi)_n$.

\index{kernel pair}
Let $f: A \to B$ in some category $\ensuremath{\mathcal{C}}$.
The \textbf{kernel pair} of $f$ is the pair $ \xymatrix{W \ar@<0.5ex>[r]^-{p} \ar@<-0.5ex>[r]_-{q} & A} $ of maps in
the pullback square
\[
\NoCompileMatrices

	\xymatrix{
		W \ar@{}[dr]|-<{\textstyle{\lrcorner}} \ar[r]^-{p} \ar[d]_-{q}
		& A \ar[d]^-{f} \\
		A \ar[r]^-{f}
		& B
	}

\]
if this pullback exists.

\label{cor:srpres}
Let $R$ be the plain operad generated by ${\ensuremath{U^{\Sigma}}} P$, satisfying exactly those
plain-operadic equations satisfied by $P$.
Then
\[
\xymatrixcolsep{4pc}
 \xymatrix{{\ensuremath{F_{\rm pl}}}{\ensuremath{U^{\rm pl}}} Q \ar@<0.5ex>[r]^-{\overline{{\ensuremath{U^{\rm pl}}} \pi_{1}}} \ar@<-0.5ex>[r]_-{\overline{{\ensuremath{U^{\rm pl}}} \pi_{2}}} & {\ensuremath{F_{\rm pl}}} {\ensuremath{U^{\Sigma}}} P} 
\]
is a presentation for $R$, where the overbars refer to transposition with
respect to the adjunction ${\ensuremath{F_{\rm pl}}} \dashv {\ensuremath{U^{\rm pl}}}$.

\label{lem:fork.epi}
If $
	\xymatrix{X \ar@<0.5ex>[r]^-{f} \ar@<-0.5ex>[r]_-{g} & Y \ar[r]^-{h} & Z }
$ is a coequalizer in some category, and if $e: W \to X$
is epi, then $
	\xymatrix{W \ar@<0.5ex>[r]^-{fe} \ar@<-0.5ex>[r]_-{ge} & Y \ar[r]^-{h} & Z }
$ is a coequalizer.

\label{lem:coeq-kerpair}
In categories with all kernel pairs, every regular epi is the coequalizer of
its kernel pair.

Let $\ensuremath{\mathcal{C}}$ be a category with pullbacks, and $T$ be a monad on $\ensuremath{\mathcal{C}}$.
Let $(
	\xymatrix{{T}{A} \ar[r]^{a} & {A}}
) \in \ensuremath{\mathcal{C}}^T$.
Let $ \xymatrix{E \ar@<0.5ex>[r]^-{\phi_1} \ar@<-0.5ex>[r]_-{\phi_2} & TA} $ be the kernel pair of $a$ in $\ensuremath{\mathcal{C}}$.
Then
\[

	\xymatrix{F_T E \ar@<0.5ex>[r]^-{\bar \phi_1} \ar@<-0.5ex>[r]_-{\bar \phi_2} & F_T A \ar[r]^-{\epsilon_{(A,a)}} & (A,a) }

\]
is a coequalizer in $\ensuremath{\mathcal{C}}^T$, where $F_T : \ensuremath{\mathcal{C}} \to \ensuremath{\mathcal{C}}^T$ is the free functor, and $\epsilon$ is the counit of the adjunction $F_T \dashv U_T$.

\label{lem:term<->tree}
\index{tree!finite product!equivalence to terms}
Every $\Phi$-term $t$ is equal to $\mathop{\rm{term}}(f \cdot \tau)$ for a unique finite
product tree $(f\cdot \tau)$.

\label{lem:syntactic_semantic_equiv}
\index{tree!permuted!equivalence to linear terms}
\index{tree!plain-operadic!equivalence to strongly regular terms}
Let $t$ be a $\Phi$-term.
Then $t$ is linear iff $t = \mathop{\rm{term}}(\tau)$ for some permuted tree $\tau$, and
strongly regular iff $t = \mathop{\rm{term}}(\tau)$ for some strongly regular tree $\tau$.

\label{lem:linpresfactor}
Let $(\Phi, E)$ be a presentation of an algebraic theory.
Then $(\Phi, E)$ is linear if and only if the projection maps $ \xymatrix{E \ar@<0.5ex>[r]^-{\pi_1} \ar@<-0.5ex>[r]_-{\pi_2} & \mathop{\rm{term}}} (\Phi)$ may be factored through the map
$\xymatrix{{\ensuremath{T_{\Sigma}}} \Phi \ar[r]^\eta & {\ensuremath{T_{\rm fp}}} \Phi \ar[r]^{\sim} & \mathop{\rm{term}}{\Phi}}$:
\[
\xymatrix{
E \ar@<0.5ex>[rr]^-{\pi_1} \ar@<-0.5ex>[rr]_-{\pi_2} \unar@<0.5ex>[dr]^-{}
	\unar@<-0.5ex>[dr]_-{}
& & {\ensuremath{T_{\rm fp}}} \Phi \ar[r]^-{\sim} & \mathop{\rm{term}} \Phi \\
& {\ensuremath{T_{\Sigma}}} \Phi \ar[r]^-{\sim} \ar[ur]_{\eta}
& \{\mbox{\rm linear $\Phi$-terms}\} \ar@{^{((}->}[ur]
}
\]

Let $Q \in {\ensuremath{\mbox{\upshape{\textbf{FP-Operad}}}}}$.
Then
\begin{enumerate}
\item $Q$ is strongly regular iff there exists a $P \in \ensuremath{\mbox{\upshape{\textbf{Operad}}}}$ such that $Q \cong {\ensuremath{F_{\rm fp}^{\rm pl}}} P$;
\item $Q$ is linear iff there exists a $P \in \ensuremath{\mbox{\upshape{\textbf{$\Sigma$-Operad}}}}$ such that $Q \cong
{\ensuremath{F_{\rm fp}^{\Sigma}}} P$;
\end{enumerate}

\index{monoids}
\index{pointed sets}
\index{commutative monoids}
The theories of monoids and pointed sets are strongly regular, because the finite product operads\ corresponding to these theories are in the image of ${\ensuremath{F_{\rm fp}^{\rm pl}}}$; the theory of
commutative monoids is linear but not strongly regular, because the finite product operad\ whose
algebras are commutative monoids is in the image of ${\ensuremath{F_{\rm fp}^{\Sigma}}}$ but not in the
image of ${\ensuremath{F_{\rm fp}^{\rm pl}}}$.

\index{wide pullback}
A \textbf{wide pullback} is a limit of a (possibly infinite) diagram of the
form
\[
\xymatrixrowsep{1pc}
\xymatrixcolsep{3pc}
\xymatrix{
	\bullet \ar[ddr] \\
	\bullet \ar[dr] \\
	\vdots & \bullet \\
	\bullet \ar[ur] \\
	\vdots
}
\]

\index{cartesian!natural transformation}
A natural transformation $\alpha : F \to G$ is \textbf{cartesian} if every
naturality square
\[

	\xymatrix{
		FA \ar[r]^-{Ff} \ar[d]_-{\alpha_A}
		& FB \ar[d]^-{\alpha_B} \\
		GA \ar[r]^-{Gf}
		& GB
	}

\]
is a pullback square.

\index{cartesian!monad}
A monad $(T, \mu, \eta)$ is \textbf{cartesian} if $T$ preserves pullbacks and
$\mu, \eta$ are cartesian natural transformations.

\label{thm:opds<=>cart. monad}
A plain operad is equivalent to a cartesian monad on \ensuremath{\mbox{\upshape{\textbf{Set}}}}\ equipped with a
cartesian map of monads to the free monoid monad.

(Carboni-Johnstone)
Let $\ensuremath{\mathcal{C}}$ be a complete, locally small, well-powered category with a small
cogenerating set, and let $F : \ensuremath{\mathcal{C}} \to \ensuremath{\mbox{\upshape{\textbf{Set}}}}$ be a functor.
The following are equivalent:
\begin{enumerate}
\item $F$ is familially representable;
\item $F$ preserves wide pullbacks.
\end{enumerate}

\index{involutive monoid}
\index{monoid with involution|see{involutive monoid}}
An \textbf{involutive monoid} (or \textbf{monoid with involution}) is a
monoid $(M,.,1)$ equipped with an involution $i : M \to M$,
satisfying $i(a.b) = i(b).i(a)$.

\index{multicategory!finite product!enriched}
A \textbf{finite product \ensuremath{\mathcal{V}}-multicategory} is
\begin{itemize}
\item A plain \ensuremath{\mathcal{V}}-multicategory \ensuremath{\mathcal{C}};
\item for every function $f : {\underline{n}} \to {\underline{m}}$ in \ensuremath{\bbF}, and for all objects $C_1,
\dots, C_n, D \in \ensuremath{\mathcal{C}}$, a morphism $f\cdot - : \ensuremath{\mathcal{C}}(C_1, \dots, C_n;D) \to
\ensuremath{\mathcal{C}}(C_{f(1)}, \dots, C_{f(n)}; D)$ in \ensuremath{\mathcal{V}}\,
\end{itemize}
satisfying the conditions given in Definition \ref{def:symmVmcat}, where
$(f\circ(f_1,\dots, f_n))$ is as given in Definition \ref{dopdef}.

\index{morphism!of enriched multicategories}
Let $\ensuremath{\mathcal{C}}$, $\ensuremath{\mathcal{D}}$ be plain \ensuremath{\mathcal{V}}-multicategories.
A \textbf{morphism} $F: \ensuremath{\mathcal{C}} \to \ensuremath{\mathcal{D}}$ is
\begin{itemize}
\item for each object $C \in \ensuremath{\mathcal{C}}$, a choice of object $FC \in \ensuremath{\mathcal{D}}$,
\item for each $n \in \natural$ and all collections of objects $A_1, \dots,
A_n, B \in \ensuremath{\mathcal{C}}$, an arrow

$ \ensuremath{\mathcal{C}}(A_1, \dots, A_n;B) \to \ensuremath{\mathcal{D}}(FA_1, \dots, FA_n; FB) $ in $\ensuremath{\mathcal{V}}$
\end{itemize}
such that
\begin{itemize}
\item for all $A \in \ensuremath{\mathcal{C}}$, the diagram
\[
\xymatrix{
 & I \ar[ddl]_u \ar[ddr]^u \\ \\
\ensuremath{\mathcal{C}}(A;A) \ar[rr]^F & & \ensuremath{\mathcal{D}}(FA;FA)
}
\]
commutes;
\item for all $n, k_1, \dots, k_n \in \natural$ and all $C, B_1, \dots, B_n, A^1_1, \dots, A^n_{k_n} \in \ensuremath{\mathcal{C}}$, the diagram
\[
\xymatrixrowsep{4pc}
\xymatrix{
\ensuremath{\mathcal{C}}(B_\bullet;C) \otimes \bigotimes_{i=1}^n \ensuremath{\mathcal{C}}(A^i_\bullet;B_i)
\ar[r]^-{\circ} \ar[d]_{F\otimes \dots \otimes F}
& \ensuremath{\mathcal{C}}(A_\bullet^\bullet;C) \ar[d]^F \\
\ensuremath{\mathcal{D}}(FB_\bullet;FC)\otimes \bigotimes_{i=1}^n \ensuremath{\mathcal{D}}(F A^i_\bullet;FB_i)
\ar[r]^-\circ
& \ensuremath{\mathcal{D}}(FA_\bullet^\bullet;FC)
}
\]
commutes.
\end{itemize}

\index{multicategory!internal}
\index{operad!internal}
There is another possibility, that of considering \emph{internal}
multicategories in the category \ensuremath{\mathcal{V}}, which gives a different notion: now
$\ensuremath{\mathcal{C}}_0$ is an object in \ensuremath{\mathcal{V}}\ rather than a collection.
An internal operad in \ensuremath{\mathcal{V}}\ is an internal multicategory \ensuremath{\mathcal{C}}\ such that $\ensuremath{\mathcal{C}}_0$ is
terminal in \ensuremath{\mathcal{V}}.
We shall not consider internal multicategories or operads further.

\index{operad!enriched!in \ensuremath{\mbox{\upshape{\textbf{Cat}}}}}
A {(plain) \ensuremath{\mbox{\upshape{\textbf{Cat}}}}-operad} $Q$ is a sequence of categories $Q_0, Q_1,
\dots$, a family of composition functors $\circ:Q_n \times Q_{k_1}
\times \ldots \times Q_{k_n} \to Q_{\sum k_i}$ and an identity 
$1_Q \in Q_1$, satisfying (strict) functorial versions of the axioms given in
\ref{lem:operad_description}.

\label{laxmorphdef}
\index{morphism!of algebras for a finite product \ensuremath{\mbox{\upshape{\textbf{Cat}}}}-operad}
Let $Q$ be a finite product \ensuremath{\mbox{\upshape{\textbf{Cat}}}}-operad, and let $Q \circ A \stackrel\alpha\to A , Q \circ B
\stackrel\beta\to B$ be algebras for $Q$ in $\ensuremath{\mbox{\upshape{\textbf{Cat}}}}$. A
\textbf{lax morphism of $Q$-algebras} $A \to B$ consists of a 1-cell $F: A \to
B$ and a 2-cell $\phi: \beta F \to F \alpha$ satisfying the
following conditions:
\begin{equation}
\label{eq:laxmorph1}
\xymatrixrowsep{3pc}
\xymatrix{
	A \ar[r]^F \ar[d]_\eta
	  \ddlowertwocell<-20>_1{=}                   
	  \drtwocell\omit{=}
	& B \ar[d]^\eta
	  \dduppertwocell<20>^1{=} \\                      
	Q\circ A \ar[r]^{1\circ F} \ar[d]_\alpha
	  \drtwocell\omit{\phi}
	& Q\circ B \ar[d]^\beta
		& & = & A \rtwocell^F_F{=} & B \\
	A \ar[r]_F & B
}
\end{equation}
\begin{equation}
\label{eq:laxmorph2}
\xymatrixcolsep{1.4pc}
\xymatrixrowsep{3pc}
\xymatrix{
	Q \circ Q \circ A \ar[d]_\mu \ar[r]^{1\circ 1\circ F}
	  \drtwocell\omit{=}
	& Q \circ Q \circ B \ar[d]^\mu
	& & & Q \circ Q \circ A \ar[dl]_\mu \ar[r]^{1\circ 1\circ F}
		\ar[d]_{1\circ \alpha}
		\drtwocell\omit{\phi}
	& Q \circ Q \circ B  \ar[dr]^\mu \ar[d]^{1\circ \beta} \\
	Q \circ A \ar[r]^{1\circ F} \ar[d]_{\alpha}
		\drtwocell\omit{\phi}
	& Q \circ B \ar[d]^{\beta}
	& =
	& Q \circ A \ar[dr]_{\alpha}
	  \rtwocell\omit{=}
	& Q \circ A \ar[r]^{1\circ F} \ar[d]_{\alpha}
		\drtwocell\omit{\phi}
	& Q \circ B \ar[d]^{\beta}
	  \rtwocell\omit{=}
	& Q \circ B \ar[dl]^{\beta} \\
	A \ar[r]_F
	& B
	& & & A \ar[r]_F
	& B
}
\end{equation}
\begin{equation}
\label{eq:laxmorph3}
\xymatrixcolsep{1.4pc}
\xymatrixnocompile{
	& Q_m \times A^n \ar[dl]_{1 \times f^*} \ar[dr]^{1 \times F^n}
		\ddtwocell\omit{=}
	& & & & Q_m \times A^n \ar[dl]_{1 \times f^*} \ar[dr]^{1 \times F^n}
		\ar[dd]^{f_* \times 1}
	\\

	Q_m \times A^m \ar[dd]^\alpha \ar[dr]^{1 \times F^m}
	& & Q_m \times B^n \ar[dl]_{1 \times f^*} \ar[dd]^{f_* \times 1}
	& & Q_m \times A^m \ar[dd]^\alpha
		\drtwocell\omit{=}
	& & Q_m \times B^n \ar[dd]^{f_* \times 1} \\

		\drtwocell\omit{\phi}
	& Q_n \times B^m \ar[dd]^\beta
		\drtwocell\omit{=}
	& & =
	& & Q_n \times A^n \ar[dl]_\alpha \ar[dr]_{1 \times F^n}
		\urtwocell\omit{=}
		\ddtwocell\omit{\phi} \\

	A \ar[dr]_F
	& & Q_n \times B^n \ar[dl]^\beta
	& & A \ar[dr]_F
	& & Q_n \times B^n \ar[dl]^\beta \\
	& B
	& & & & B
}
\end{equation}
for all functions $f : {\underline{m}} \to {\underline{n}}$.

A morphism $(F,\phi)$ is \textbf{weak} if $\phi$ is invertible, and
\textbf{strict} if $\phi$ is an identity.
\index{weak!morphism of algebras for a finite product \ensuremath{\mbox{\upshape{\textbf{Cat}}}}-operad}
\index{strict!morphism of algebras for a finite product \ensuremath{\mbox{\upshape{\textbf{Cat}}}}-operad}

\index{morphism!of algebras for a symmetric \ensuremath{\mbox{\upshape{\textbf{Cat}}}}-operad}
\index{lax!morphism of algebras for a symmetric \ensuremath{\mbox{\upshape{\textbf{Cat}}}}-operad}
\index{weak!morphism of algebras for a symmetric \ensuremath{\mbox{\upshape{\textbf{Cat}}}}-operad}
\index{strict!morphism of algebras for a symmetric \ensuremath{\mbox{\upshape{\textbf{Cat}}}}-operad}
Lax morphisms for algebras of plain \ensuremath{\mbox{\upshape{\textbf{Cat}}}}-operads are required to satisfy
\ref{eq:laxmorph1} and \ref{eq:laxmorph2}, and lax morphisms for algebras of
symmetric \ensuremath{\mbox{\upshape{\textbf{Cat}}}}-operads are required to satisfy \ref{eq:laxmorph1},
\ref{eq:laxmorph2} and the restriction of \ref{eq:laxmorph3} to the case where
$f$ is a bijection.

\label{lem:wkfunc_explicit}
Let $Q$ be a plain $\ensuremath{\mbox{\upshape{\textbf{Cat}}}}$-operad, and let $(A,h)$ and $(B,h')$ be $Q$-algebras.
A lax map of $Q$-algebras $(A,h) \to (B,h')$ is a pair $(G, \psi)$,
where $G:A \to B$ is a functor and $\psi$ is a sequence of natural
transformations $\psi_i : h'_i (1 \times G^i) \to G h_i$, called the
\textbf{coherence maps}, such that the following equation holds, for all $n,
k_1, \dots, k_n \in \natural$:
\[

\xymatrixrowsep{4pc}
\xymatrixcolsep{4pc}
\xymatrix{
	Q_n \times Q_{k_1} \times \dots \times Q_{k_n} \times A^{\sum k_i}
		\ar[d]_{1\times 1^n \times G^{\sum k_i}}
		\ar[r]^-{h_{k_1} \times \dots \times h_{k_n}}
		\drtwocell\omit{^*{!(-1,-1.5)\object{\psi_{k_1} \times \dots \times \psi_{k_n}}}}

	& Q_n \times A^n
		\ar[d]|{1\times G^n}
		\ar[r]^{h_n}
		\drtwocell\omit{^*{!(-1,-1.5)\object{\psi_n}}}

	& A
		\ar[d]^G
		\\
	Q_n \times Q_{k_1} \times \dots \times Q_{k_n} \times A^{\sum k_i}
		\ar[r]_-{h'_{k_1} \times \dots \times h'_{k_n}}
	& Q_n \times B^n
		\ar[r]_{h'}
	& B \\
}
\hskip 1in
\]
\begin{equation}
\label{weakfunctordef}
\hskip 2in

	        \xymatrixrowsep{4pc}
		\xymatrixcolsep{4pc}
		\xymatrix{ {} \ar @{}[d]^{=} \\ {} }


\xymatrix{
	Q_n \times Q_{k_1} \times \dots \times Q_{k_n} \times A^{\sum k_i}
		\ar[d]_{1\times 1^n \times G^{\sum k_i}}
		\ar[r]^-{h_{\sum k_i}}

		\drtwocell\omit{^*{!(-1.5,-2.5)\object{\psi_{\sum k_i}}}}
	& A
		\ar[d]^G
		\\
	Q_n \times Q_{k_1} \times \dots \times Q_{k_n} \times B^{\sum k_i}
		\ar[r]_-{h'_{\sum k_i}}
	& B \\
}
\end{equation}
and the diagram
\begin{equation}
\label{weakfunctordef2}
\xymatrixrowsep{3pc}
\xymatrixcolsep{3pc}
\xymatrix{
	G a \ar[r]^{\delta'_1} \ar[d]_1
	& h'(1_P, G a) \ar[d]^{\psi_1} \\
	G a \ar[r]_{G \delta_1}
	& G h(1_P, a)
}
\end{equation}
commutes.
The morphism is weak if every $\psi$ is invertible, and
strict if every $\psi$ is an identity.

\label{transfdef}
\index{transformation!between morphisms of algebras for a \ensuremath{\mbox{\upshape{\textbf{Cat}}}}-operad}
Let $Q, A, B$ etc.\ be as above, and let $(F,\phi), (G,\gamma)$ be lax
morphisms of $Q$-algebras $A \to B$.
A \textbf{$Q$-transformation} $F \to G$ is a natural transformation $\sigma:
F \to G$ such that
\begin{equation}
\xymatrixrowsep{1pc}
\xymatrix{
	Q \circ A \rtwocell^{1\circ F}_{1\circ G}{\sigma} \ar[dd]_\alpha
		\ddrtwocell\omit{\gamma}
	& Q \circ B \ar[dd]^\beta
	& & Q \circ A \ar[r]^{1 \circ F} \ar[dd]_\alpha
		\ddrtwocell\omit{\phi}
	& Q \circ B \ar[dd]^\beta \\
	& & = \\
	A \ar[r]_G
	& B
	& & A \rtwocell^F_G{\sigma}
	& B
}
\end{equation}

\label{inv <=> Q-inv}
A $Q$-transformation $\sigma: (F, \phi) \to (G, \psi)$ is invertible as a
natural transformation if and only if it is invertible as a $Q$-transformation.

There is a chain of monadic adjunctions
\index{adjunctions!for \ensuremath{\mbox{\upshape{\textbf{Cat}}}}-operads}
\begin{equation}
\label{eqn:cat_adjs}
\xymatrixrowsep{3pc}
\xymatrix{
  {\ensuremath{\mbox{\upshape{\textbf{\ensuremath{\mbox{\upshape{\textbf{Cat}}}}-FP-Operad}}}}} \ar@<1.2ex>[d]^{\ensuremath{U^{\rm fp}_{\Sigma}}}
	 \ar@/r1.7cm/[dd]^{\ensuremath{U^{\rm fp}_{\rm pl}}}
	 \ar@/r3cm/[ddd]^{\ensuremath{U^{\rm fp}}} \\
  \ensuremath{\mbox{\upshape{\textbf{Cat-$\Sigma$-Operad}}}} \ar@<1.2ex>[d]^{\ensuremath{U^{\Sigma}_{\rm pl}}} \ar@<1.2ex>[u]^{\ensuremath{F_{\rm fp}^{\Sigma}}}_{\dashv}
	 \ar@/r1.7cm/[dd]^{\ensuremath{U^{\Sigma}}} \\
  \ensuremath{\mbox{\upshape{\textbf{Cat-Operad}}}} \ar@<1.2ex>[u]^{\ensuremath{F_{\Sigma}^{\rm pl}}}_{\dashv} \ar@<1.2ex>[d]^{\ensuremath{U^{\rm pl}}}
	 \ar@/l1.7cm/[uu]^{\ensuremath{F_{\rm fp}^{\rm pl}}} \\
  \ensuremath{\mbox{\upshape{\textbf{Cat}}}}^\natural \ar@<1.2ex>[u]^{\ensuremath{F_{\rm pl}}}_{\dashv} \ar@/l1.7cm/[uu]^{\ensuremath{F_{\Sigma}}} 
  	 \ar@/l3cm/[uuu]^{\ensuremath{F_{\rm fp}}}
}
\end{equation}

\index{orthogonal}
Let $e: a \to b$ and $m: c \to d$ be arrows in a category \ensuremath{\mathcal{C}}.
We say that $e$ is \textbf{left orthogonal} to $m$, written $e \mathop{\bot} m$, if,
for all arrows $f: a \to c$ and $g: b \to d$ such that $mf = ge$, there exists
a unique map $t: b \to c$ such that the following diagram commutes:
\[
\xymatrix{
	a \ar[r]^{\forall f} \ar[d]_e
	& c \ar[d]^m \\
	b \ar@{..>}[ur]^{\exists! t} \ar[r]_{\forall g}
	& d
}
\]

\label{def:FS}
\index{factorization system}
Let \ensuremath{\mathcal{C}}\ be a category.
A \textbf{factorization system} on \ensuremath{\mathcal{C}}\ is a pair $(\ensuremath{\mathcal{E}}, \ensuremath{\mathcal{M}})$ of classes of maps
in \ensuremath{\mathcal{C}}\ such that
\begin{enumerate}
\item \label{axm:factor} for all maps $f$ in \ensuremath{\mathcal{C}}, there exist $e \in \ensuremath{\mathcal{E}}$ and $m
\in \ensuremath{\mathcal{M}}$ such that $f = m  e$;
\item \label{axm:iso_closure} \ensuremath{\mathcal{E}}\ and \ensuremath{\mathcal{M}}\ contain all identities, and are
closed under composition with isomorphisms on both sides;
\item \label{axm:orthogonal} $\ensuremath{\mathcal{E}} \mathop{\bot} \ensuremath{\mathcal{M}}$, i.e. $e \mathop{\bot} m$ for all $e \in
\ensuremath{\mathcal{E}}$ and $m \in \ensuremath{\mathcal{M}}$.
\end{enumerate}

\label{ex:epi-mono}
\index{factorization system!epi-mono}
Let $\ensuremath{\mathcal{C}} = \ensuremath{\mbox{\upshape{\textbf{Set}}}}$, $\ensuremath{\mathcal{E}}$ be the epimorphisms, and $\ensuremath{\mathcal{M}}$ be the monomorphisms.
Then $(\ensuremath{\mathcal{E}},\ensuremath{\mathcal{M}})$ is a factorization system.

\index{factorization system!bijective on objects/full and faithful!on \ensuremath{\mbox{\upshape{\textbf{Digraph}}}}}
\label{ex:digraphFS}
Let $\ensuremath{\mathcal{C}} = \ensuremath{\mbox{\upshape{\textbf{Digraph}}}}$, the category of directed graphs and graph morphisms.
Let $\ensuremath{\mathcal{E}}$ be the maps bijective on objects, and \ensuremath{\mathcal{M}}\ be the full and faithful
maps.
Then $(\ensuremath{\mathcal{E}},\ensuremath{\mathcal{M}})$ is a factorization system.

\label{lem:fact_standard}
Let \ensuremath{\mathcal{C}}\ be a category, and $(\ensuremath{\mathcal{E}}, \ensuremath{\mathcal{M}})$ be a factorization system on \ensuremath{\mathcal{C}}.
\begin{enumerate}
\item $\ensuremath{\mathcal{E}} \cap \ensuremath{\mathcal{M}}$ is the class of isomorphisms in \ensuremath{\mathcal{C}}.
\item \label{fact_unique} The factorization in \ref{def:FS} (\ref{axm:factor})
is unique up to unique isomorphism.
\item The factorization in \ref{def:FS} (\ref{axm:factor}) is functorial, in
the following sense: if the square
\[

	\xymatrix{
		A \ar[r]^-{f} \ar[d]_-{g}
		& B \ar[d]^-{h} \\
		C \ar[r]^-{f'}
		& D
	}

\]
commutes, and $f = me, f' = m'e'$, then there is a unique morphism $i$ making
\[
\xymatrix{
	A \ar@{->>}[r]^{e} \ar[d]_g
	& {} \ar@{(>->}[r]^{m} \ar@{..>}[d]_i
	& B \ar[d]^h \\
	C \ar@{->>}[r]^{e'}
	& {} \ar@{(>->}[r]^{m'}
	& D
}
\]
commute.
Thus, given a choice of $e \in \ensuremath{\mathcal{E}}$ and $m \in \ensuremath{\mathcal{M}}$ for each $f$ in \ensuremath{\mathcal{C}} (such that
$f = me$), we may construct functors $\ensuremath{\mathcal{E}}_*, \ensuremath{\mathcal{M}}_* : [\ensuremath{\mbox{\upshape{\textbf{2}}}}, \ensuremath{\mathcal{C}}] \to [\ensuremath{\mbox{\upshape{\textbf{2}}}},
\ensuremath{\mathcal{C}}]$:
\begin{eqnarray*}
& \ensuremath{\mathcal{E}}_* : f \mapsto e \\
& \ensuremath{\mathcal{E}}_* : (g,h) \mapsto (g,i) \\
& \ensuremath{\mathcal{M}}_* : f \mapsto m \\
& \ensuremath{\mathcal{M}}_* : (g,h) \mapsto (i,h).
\end{eqnarray*}
These functors are determined by \ensuremath{\mathcal{E}}\ and \ensuremath{\mathcal{M}}\ uniquely up to unique isomorphism.
\item \ensuremath{\mathcal{E}}\ and \ensuremath{\mathcal{M}}\ are closed under composition.
\item $\ensuremath{\mathcal{E}}^{\bot} = \ensuremath{\mathcal{M}}$ and ${}^{\bot} \ensuremath{\mathcal{M}} = \ensuremath{\mathcal{E}}$, where $\ensuremath{\mathcal{E}}^{\bot} = \{f
\mbox{ in } \ensuremath{\mathcal{C}} : e \mathop{\bot} f \mbox{ for all } e \in \ensuremath{\mathcal{E}}\}$ and $^{\bot}\ensuremath{\mathcal{M}} = \{f
\mbox{ in } \ensuremath{\mathcal{C}} : f \mathop{\bot} m \mbox{ for all } m \in \ensuremath{\mathcal{M}}\}$.
\end{enumerate}

This is established in \cite{acc}, Proposition 20.24: however, we shall provide
a proof for the reader's convenience.
We shall establish the axioms listed in Definition \ref{def:FS}.

\ref{axm:factor}.
Take an algebra map
\[



	\xymatrix{
		T A \ar[r]^-{T f} \ar[d]_-{a}
		& T B \ar[d]^-{b} \\
		A \ar[r]^-{f}
		& B
	}


\]
Applying axiom \ref{axm:factor} to the factorization system $(\ensuremath{\mathcal{E}}, \ensuremath{\mathcal{M}})$, we
obtain a decomposition $f = m  e$, where $e: A \to I$ and $m: I \to B$.
We wish to lift this to a decomposition of $f$ as an algebra map.
In other words, we need a map $i: TI \to I$ making the diagram
\[
\xymatrix{
	TA \ar@{->>}[r]^{Te} \ar[d]_a
	& TI \ar[r]^{Tm} \ar@{..>}[d]_i
	& TB \ar[d]^b \\
	A \ar@{->>}[r]^e
	& I \ar@{(>->}[r]^m
	& B
}
\]
commute, such that $(I,i)$ is a $T$-algebra.
Since $T$ preserves \ensuremath{\mathcal{E}}-arrows, $T e \mathop{\bot} m$, and we may obtain $i$ by
applying this orthogonality to the diagram \[
\xymatrixrowsep{3pc}
\xymatrix{
	TA \ar[r]^{a} \ar[d]_{T e}
	& A \ar[r]^e
	& I \ar[d]^m \\
	TI \ar[r]_{Tm} \ar@{..>}[urr]^{\exists!i}
	& TB \ar[r]_b
	& B.
}
\]
It remains to show that $(I,i)$ is a $T$-algebra.
For the unit axiom, consider the diagram
\[
\xymatrix{
	A \ar@{->>}[r]^e \ar[d]^{\eta_A} \ar@/l1cm/[dd]_1
	& I \ar@{(>->}[r]^m \ar[d]^{\eta_I} & B \ar[d]^{\eta_B} \ar@/r1cm/[dd]^1\\
	TA \ar@{->>}[r]^{Te} \ar[d]_a & TI \ar[r]^{Tm} \ar[d]^i & TB \ar[d]^b \\
	A \ar@{->>}[r]_e & E \ar@{(>->}[r]_m & B
}
\]
The top squares commute by naturality, and the outside triangles commute since $(A,a)$ and $(B,b)$ are $T$-algebras.
Hence the diagram
\[
\xymatrix{
	& I \ar@{(>->}[dr]^m \ar@{..>}[dd] \\
	A \ar@{->>}[ur]^e \ar@{->>}[dr]_e & & B \\
	& I \ar@{(>->}[ur]_m
}
\]
commutes if the dotted arrow is either $1_I$ or $i\eta_I$.
By orthogonality, $i\eta_I = 1_I$.

For the multiplication axiom, observe that the diagrams
\[
\xymatrixcolsep{3pc}
\xymatrixrowsep{3pc}
\xymatrix{
	T^2 A \ar@{->>}[r]^{T^2 e} \ar[d]_{\mu_A}
	& T^2 I \ar[r]^{T^2 m} \ar[d]^{\mu_I}
	& T^2 B \ar[d]^{\mu_B} \\
	TA \ar@{->>}[r]^{Te} \ar[d]_a & TI \ar[r]^{Tm} \ar[d]^i & TB \ar[d]^b \\
	A \ar@{->>}[r]_e & E \ar@{(>->}[r]_m & B
}
\hskip 1cm
\xymatrix{
	T^2 A \ar@{->>}[r]^{T^2 e} \ar[d]_{T a} \ar@/l1cm/[dd]_{a\mu_A}
	& T^2 I \ar[r]^{T^2 m} \ar[d]^{T i}
	& T^2 B \ar[d]^{T b} \ar@/r1cm/[dd]^{b\mu_B} \\
	TA \ar@{->>}[r]^{Te} \ar[d]_a & TI \ar[r]^{Tm} \ar[d]^i & TB \ar[d]^b \\
	A \ar@{->>}[r]_e & E \ar@{(>->}[r]_m & B
}
\]
both commute.
So the diagram
\[
\xymatrixcolsep{3pc}
\xymatrixrowsep{3pc}
\xymatrix{
	T^2 A \ar[r]^{\mu_A} \ar@{->>}[d]_{T^2 e}
		& TA \ar[r]^a & A \ar[r]^e & I \ar@{(>->}[d]^m \\
	T^2 I \ar[r]_{T^2 m} \ar@{..>}[urrr]
		& T^2 B \ar[r]_{\mu_B} & TB \ar[r]_b & B
}
\]
commutes if we take the dotted arrow to be either $i\mu_I$ or $i(Ti)$.
By orthogonality, $i\mu_I = i(Ti)$.

\ref{axm:iso_closure}.  
The image under $U$ of an isomorphism in $\ensuremath{\mathcal{C}}^T$ is an isomorphism in \ensuremath{\mathcal{C}}.
The class \ensuremath{\mathcal{E}}\ contains all isomorphisms in \ensuremath{\mathcal{C}}, so $\overline \ensuremath{\mathcal{E}} = U^{-1}(\ensuremath{\mathcal{E}})$ contains
all isomorphisms in $\ensuremath{\mathcal{C}}^T$.
By similar reasoning, $\overline \ensuremath{\mathcal{E}}$ is closed under composition with isomorphisms,
and $\overline \ensuremath{\mathcal{M}}$ also satisfies these conditions.

\ref{axm:orthogonal}.
We wish to show that $\overline \ensuremath{\mathcal{E}} \mathop{\bot} \overline \ensuremath{\mathcal{M}}$.
Take $T$-algebras
\[

	\mbox{$\left(\begin{matrix}
		{T}{A} \cr \phantom{a} \Big\downarrow {a} \cr {A}
	\end{matrix}\right)$}
,

	\mbox{$\left(\begin{matrix}
		{T}{B} \cr \phantom{b} \Big\downarrow {b} \cr {B}
	\end{matrix}\right)$}
,

	\mbox{$\left(\begin{matrix}
		{T}{I} \cr \phantom{i} \Big\downarrow {i} \cr {I}
	\end{matrix}\right)$}
,

	\mbox{$\left(\begin{matrix}
		{T}{J} \cr \phantom{j} \Big\downarrow {j} \cr {J}
	\end{matrix}\right)$}

\]
and algebra maps
\[



	\xymatrix{
		T A \ar[r]^-{T e} \ar[d]_-{a}
		& T I \ar[d]^-{i} \\
		A \ar[r]^-{e}
		& I
	}

,



	\xymatrix{
		T J \ar[r]^-{T m} \ar[d]_-{j}
		& T B \ar[d]^-{b} \\
		J \ar[r]^-{m}
		& B
	}

,



	\xymatrix{
		T A \ar[r]^-{T f} \ar[d]_-{a}
		& T J \ar[d]^-{j} \\
		A \ar[r]^-{f}
		& J
	}

,



	\xymatrix{
		T I \ar[r]^-{T g} \ar[d]_-{i}
		& T B \ar[d]^-{b} \\
		I \ar[r]^-{g}
		& B
	}


\]
where the first two maps are in $\overline \ensuremath{\mathcal{E}}$ and $\overline \ensuremath{\mathcal{M}}$ respectively.
Suppose that $ge = mf$.
Now, $e \in \ensuremath{\mathcal{E}}$ and $m \in \ensuremath{\mathcal{M}}$, so $e \mathop{\bot} m$, and there is a unique map $t$
in \ensuremath{\mathcal{C}}\ such that
\[

	\xymatrix{
		A \ar[r]^-{f} \ar[d]_-{e}
		& J \ar[d]^-{m} \\
		I \ar@{..>}[ur]^{\exists! t} \ar[r]^-{g}
		& B
	}

\]
commutes.
We wish to show that $t$ is a map of $T$-algebras.

Consider the diagram
\[
\xymatrix{
	TA \ar[r]^{Te} \ar[d]_a \ar@/u0.7cm/[rr]^{Tf}
	&TI \ar[r]^{Tt} \ar[d]_i \ar@/u0.7cm/[rr]^{Tg}
	& TJ \ar[r]^{Tm} \ar[d]^j
	& TB \ar[d]^b \\
	A \ar[r]^e \ar@/d0.7cm/[rr]_f
	& I \ar[r]^t \ar@/d0.7cm/[rr]_g
	& J \ar[r]^m
	& B
}
\]
We wish to show that the middle square commutes: the assumptions tell us that
all other squares commute.
Recall that $T e \mathop{\bot} m$, and apply orthogonality to the square
\[

	\xymatrix{
		TA \ar[r]^-{j Tf} \ar[d]_-{Te}
		& J \ar[d]^-{m} \\
		TI \ar@{..>}[ur]^{\exists!u} \ar[r]^-{gi}
		& B
	}

\]
Now,
\[
\begin{array}{rcll}
j(Tf)	&= & fa		& \mbox{($f$ is a map of $T$-algebras)} \\
	&= & tea	& \mbox{(Definition of $t$)} \\
	&= & ti(Te)	& \mbox{($e$ is a map of $T$-algebras)} \\
\end{array}
\]
and $mti = gi$ by definition of $t$, so $ti = u$ by uniqueness.
Similarly,
\[
\begin{array}{rcll}
gi	&= & b(Tg)	& \mbox{($g$ is a map of $T$-algebras)} \\
	&= & b(Tm)(Tt)	& \mbox{(Definition of $t$)} \\
	&= & mj(Tt)	& \mbox{($m$ is a map of $T$-algebras)} \\
\end{array}
\]
and $j(Tf) = j(Tt)(Te)$ by definition of $t$, so $j(Tt) = u$ by uniqueness.
Hence $j(Tt) = ti$, and $t$ is a map of $T$-algebras.

By construction, $t$ is unique.
So $e \mathop{\bot} m$ in $\ensuremath{\mathcal{C}}^T$, so $\overline \ensuremath{\mathcal{E}} \mathop{\bot} \overline \ensuremath{\mathcal{M}}$.
All the axioms are satisfied, and so $(\overline \ensuremath{\mathcal{E}}, \overline \ensuremath{\mathcal{M}})$ is a factorization
system on $\ensuremath{\mathcal{C}}^T$.

\label{def:weakening}
\index{unbiased!weakening of a plain operad}
\index{weakening!of a plain operad}
The \textbf{unbiased weakening of $P$}, {\ensuremath{\mbox{\upshape Wk($P$)}}}, is the following \ensuremath{\mbox{\upshape{\textbf{Cat}}}}-operad:
\begin{itemize}
\item \emph{1-cells:} 1-cells of $D_* {\ensuremath{F_{\rm pl}}}{\ensuremath{U^{\rm pl}}} P$;
\item \emph{2-cells:} if $A, B \in ({\ensuremath{F_{\rm pl}}}{\ensuremath{U^{\rm pl}}} P)_n$, there is a single 2-cell $A
\to B$ if $\epsilon(A) = \epsilon(B)$ (where $\epsilon$ is the counit
of the adjunction ${\ensuremath{F_{\rm pl}}} \dashv {\ensuremath{U^{\rm pl}}}$), and no 2-cells $A \to B$ otherwise;
\item \emph{Composition of 2-cells:} the composite of two arrows $A \rightarrow
B \rightarrow C$ is the unique arrow $A \rightarrow C$, and in particular, the
arrows $A \rightarrow B$ and $B \rightarrow A$ are inverses;
\item \emph{Operadic composition:} on 1-cells, as in ${\ensuremath{F_{\rm pl}}}{\ensuremath{U^{\rm pl}}} P$, and on 2-cells,
determined by the uniqueness property.
\end{itemize}

\label{thm:WkP_characterization}
${\ensuremath{\mbox{\upshape Wk($P$)}}}$ is the unique \ensuremath{\mbox{\upshape{\textbf{Cat}}}}-operad with the following properties:
\begin{itemize}
\item ${\ensuremath{\mbox{\upshape Wk($P$)}}}$ has the same 1-cells as $D_* {\ensuremath{F_{\rm pl}}}{\ensuremath{U^{\rm pl}}} P$;
\item we may extend the counit $\epsilon_P : {\ensuremath{F_{\rm pl}}}{\ensuremath{U^{\rm pl}}} P \to  P$ to a map of
\ensuremath{\mbox{\upshape{\textbf{Cat}}}}-operads ${\ensuremath{\mbox{\upshape Wk($P$)}}} \to D_* P$, which is full and faithful levelwise.
\end{itemize}

\label{def:wkpcat}
\index{weak!$P$-category}
A \textbf{weak $P$-category} is an algebra for {\ensuremath{\mbox{\upshape Wk($P$)}}}.

\index{weak!$P$-functor}
\index{strict!$P$-functor}
Let $(A, h)$ and $(B, h')$ be weak $P$-categories. A \textbf{weak
$P$-functor} from $(A, h)$ to $(B, h')$ is a weak map of ${\ensuremath{\mbox{\upshape Wk($P$)}}}$-algebras.
A \textbf{strict $P$-functor} from $(A, h)$ to $(B, h')$ is a strict map of
${\ensuremath{\mbox{\upshape Wk($P$)}}}$-algebras.

\label{cor:triv<=>initial}
A monad $(T, \mu, \eta)$ on $\ensuremath{\mathcal{C}}$ is trivial if and only if it is isomorphic to
the identity monad on $\ensuremath{\mathcal{C}}$.

\emph{The trivial theory:}
\label{ex:trivial_theory}
\index{sets}
Let $0$ be the initial operad, whose algebras are sets.
An unbiased weak $0$-category is a category equipped with a specified trivial
monad, for the following reason.
$0$ has only one operator (call it $I$), of arity one. Hence $({\ensuremath{F_{\rm pl}}}{\ensuremath{U^{\rm pl}}} 0)_1
\cong \natural$, and all other $({\ensuremath{F_{\rm pl}}}{\ensuremath{U^{\rm pl}}} 0)_n$'s are empty.
All derived operations in the theory of sets are composites of identities, and
thus equivalent to the identity.
So all objects of ${\ensuremath{\mbox{\upshape Wk($0$)}}}_1$ are isomorphic.
Hence, $I \cong \mbox{id}$.
All diagrams commute: in particular, those giving the monad and monad morphism
axioms commute, so in any weak $0$-category $(\ensuremath{\mathcal{C}}, (\hat{\phantom{\alpha}}))$, the functor
$\hat I$ is a monad, and the isomorphism $\hat I \to 1_\ensuremath{\mathcal{C}}$ is an isomorphism of
monads.
By Corollary \ref{cor:triv<=>initial}, $\hat I$ must be trivial.

Conversely, suppose $T$ is a trivial monad on a category $\ensuremath{\mathcal{C}}$.
We wish to show that $\mu$ is also invertible, and thus that $\ensuremath{\mathcal{C}}$ is an
unbiased weak $0$-category.
From the monad axioms, we have that
\[
\xymatrix{
	T \ar[r]^{\eta T} \ar[dr]_{\mbox{id}}
	& T^2 \ar[d]^{\mu} \\
	& T
}
\]
commutes.
But $\eta T$ is invertible, so $\mu$ must be its inverse.
So $\mbox{id} \cong T \cong T^2 \cong T^3 \cong \ldots$, and all diagrams
commute.
Hence $\ensuremath{\mathcal{C}}$ is an unbiased weak $0$-category.

If $(\ensuremath{\mathcal{C}}, S)$ and $(\ensuremath{\mathcal{D}}, T)$ are weak $0$-categories, then a weak $0$-functor
$(\ensuremath{\mathcal{C}}, S) \to (\ensuremath{\mathcal{D}}, T)$ is a functor $F: \ensuremath{\mathcal{C}} \to \ensuremath{\mathcal{D}}$ and a natural isomorphism 
$\phi : TF \to FS$, such that the equations 
\[
\xymatrix{
	& \ensuremath{\mathcal{C}} \ar[dl]_S \ar[dd]^S  \ar[rr]^F \ddrrtwocell\omit{^\phi^{-1}}
	& & \ensuremath{\mathcal{D}} \ar[dd]^T \\
	\ensuremath{\mathcal{C}} \ar[dr]_S  \\
	& \ensuremath{\mathcal{C}} \ar[rr]_F \uuuppertwocell\omit{<-3>\mu} & & D
}
\xymatrix{{} \\ = \\ {}}
\xymatrix{
	& \ensuremath{\mathcal{C}} \ar[dl]_S \ar[rr]^F \drtwocell\omit{^\phi^{-1}}
	& & \ensuremath{\mathcal{D}} \ar[dd]^T \ar[dl]_T \\
	\ensuremath{\mathcal{C}} \ar[dr]_S  \ar[rr]^F 
	& {} \drtwocell\omit{^\phi^{-1}} & D \ar[dr]_T \\
	& \ensuremath{\mathcal{C}} \ar[rr]_F  & & D \uuuppertwocell\omit{<-3>\mu}
}
\]
and
\[
\xymatrix{
	\ensuremath{\mathcal{C}} \ddlowertwocell<-10>_{1_\ensuremath{\mathcal{C}}}{^\eta} \ar[dd]^S \ar[rr]^F
		\ddrrtwocell\omit{^\phi^{-1}}
	& & \ensuremath{\mathcal{D}} \ar[dd]^T \\ \\
	\ensuremath{\mathcal{C}} \ar[rr]_F & & \ensuremath{\mathcal{D}}
}
\xymatrix{{} \\ = \\ {}}
\xymatrix{
	\ensuremath{\mathcal{C}}  \ddrrtwocell\omit{^\phi^{-1}} \ar[rr]^F \ar[dd]_{1_\ensuremath{\mathcal{C}}}
	& & \ensuremath{\mathcal{D}} \dduppertwocell<10>^T{^\eta} \ar[dd]_{1_\ensuremath{\mathcal{D}}} \\ \\
	\ensuremath{\mathcal{C}} \ar[rr]_F & & \ensuremath{\mathcal{D}}
}
\]
are satisfied.

\emph{Monoids:}
\label{ex:monoids}
\index{monoids}
An unbiased weak $1$-category is precisely an unbiased weak monoidal
category in the sense of Definition \ref{def:umoncat}.
An unbiased weak $1$-functor is an unbiased weak monoidal functor.
For a proof, see \cite{hohc} Theorem 3.2.2.

\label{def:wkPphicat}
\index{weak!$P$-category}
Let $\phi, \Phi$ and $P$ be as above.
A \textbf{$\phi$-weak $P$-category} is an algebra for ${\ensuremath{\mbox{\upshape Wk$_{\phi}(P)$}}}$.

\index{weak!$P$-functor}
Let $\phi, \Phi$ and $P$ be as above.
A \textbf{$\phi$-weak $P$-functor} is a weak map of ${\ensuremath{\mbox{\upshape Wk$_{\phi}(P)$}}}$-algebras.

\index{weakening!of a symmetric operad}
Let $P$ be a symmetric operad, and $ \xymatrix{{\ensuremath{F_{\Sigma}}} E \ar@<0.5ex>[r]^-{e_1} \ar@<-0.5ex>[r]_-{e_2} & {\ensuremath{F_{\Sigma}}}
\Phi} $ be a presentation for $P$, with $\phi: {\ensuremath{F_{\Sigma}}} \Phi \to P$ being the
regular epi in Definition \ref{def:opd_presentation}.
The \textbf{weakening of $P$ with respect to $(\Phi, E)$} is the weakening of
$P$ with respect to $\phi$.

\label{def:wkp}
\index{unbiased!weakening of a symmetric operad}
The \textbf{unbiased} weakening of $P$ is the weakening arising from
the counit $\epsilon: {\ensuremath{F_{\Sigma}}}{\ensuremath{U^{\Sigma}}} P \to P$ of the adjunction ${\ensuremath{F_{\Sigma}}} \dashv
{\ensuremath{U^{\Sigma}}}$.
Call this symmetric \ensuremath{\mbox{\upshape{\textbf{Cat}}}}-operad {\ensuremath{\mbox{\upshape Wk($P$)}}}.

\label{thm:plain_as_symmetric}
\index{weakening!of a plain operad!considered as a symmetric operad}
Let $P$ be a plain operad, let $\Phi$ be a signature, and let $\phi : {\ensuremath{F_{\rm pl}}} \Phi
\to P$ be a regular epi.
Then ${\ensuremath{\mbox{\upshape Wk$_{{\ensuremath{F_{\Sigma}^{\rm pl}}} \phi}({\ensuremath{F_{\Sigma}^{\rm pl}}} P)$}}} \cong {\ensuremath{F_{\Sigma}^{\rm pl}}} ({\ensuremath{\mbox{\upshape Wk$_{\phi}(P)$}}})$ in the
category $\ensuremath{\mbox{\upshape{\textbf{Cat-$\Sigma$-Operad}}}}$.

\index{symmetric monoidal category}
A \textbf{symmetric monoidal category} is a 7-tuple $\ensuremath{(\ensuremath{\mathcal{C}}, \otimes, I, \alpha, \lambda, \rho, \tau)}$, where
\begin{itemize}
\item $\ensuremath{\mathcal{C}}$ is a category;
\item $\otimes : \ensuremath{\mathcal{C}} \times \ensuremath{\mathcal{C}} \to \ensuremath{\mathcal{C}}$ is a functor;
\item $I$ is an object of $\ensuremath{\mathcal{C}}$,
\item $\alpha: A \otimes (B \otimes C) \to (A \otimes B) \otimes C$ is natural
in $A, B, C \in \ensuremath{\mathcal{C}}$;
\item $\lambda : I \otimes A \to A$ and $\rho : A \otimes I \to A$ are natural in $A \in \ensuremath{\mathcal{C}}$;
\item $\tau : A \otimes B \to B \otimes A$ is natural in $A, B \in \ensuremath{\mathcal{C}}$,
\end{itemize}
$\alpha, \lambda, \rho, \tau$ are all invertible, and the following diagrams
commute:
\begin{equation}
\xymatrix{
& (A \otimes B) \otimes (C \otimes D) \ar[ddr]^\alpha \\
A \otimes (B \otimes (C \otimes D)) \ar[dd]_{1\otimes\alpha} \ar[ur]^\alpha \\
& & ((A \otimes B) \otimes C) \otimes D \\
A \otimes ((B \otimes C) \otimes D) \ar[dr]_\alpha \\
& (A \otimes (B \otimes C) ) \otimes D \ar[uur]_{\alpha \otimes 1}
}
\end{equation}
\begin{equation}
\xymatrix{
A \otimes (I \otimes C) \ar[rr]^\alpha \ar[ddr]_{1 \otimes \lambda}
& & (A \otimes I) \otimes C \ar[ddl]^{\rho \otimes 1} \\ \\
& A \otimes C
}
\end{equation}
\begin{equation}
\xymatrix{
A \otimes I \ar[rr]^\tau \ar[ddr]_\rho && I \otimes A\ar[ddl]^\lambda \\ \\
& A
}
\end{equation}
\begin{equation}
\xymatrix{
(A \otimes B) \otimes C \ar[r]^\tau \ar[d]_{\alpha^{-1}}
& C \otimes (A \otimes B) \ar[d]^\alpha \\
A \otimes (B \otimes C) \ar[d]_{1 \otimes \tau}
& (C \otimes A) \otimes B \ar[d]^{\tau \otimes 1} \\
A \otimes (C \otimes B) \ar[r]^\alpha
& (A \otimes C) \otimes B
}
\hskip 2em
\xymatrix{
A \otimes (B \otimes C) \ar[r]^\tau \ar[d]_\alpha
& (B \otimes C) \otimes A \ar[d]^{\alpha^{-1}} \\
(A \otimes B) \otimes C \ar[d]_{\tau \otimes 1}
& B \otimes (C \otimes A) \ar[d]^{1 \otimes \tau} \\
(B \otimes A) \otimes C \ar[r]^{\alpha^{-1}}
& B \otimes (A \otimes C)
}
\end{equation}
\begin{equation}
\xymatrix{
A \otimes B \ar[dr]_1 \ar[r]^{\tau_{A,B}} & B \otimes A \ar[d]^{\tau_{B,A}} \\
& A \otimes B.
}
\end{equation}

Let $M = \ensuremath{(\ensuremath{\mathcal{C}}, \otimes, I, \alpha, \lambda, \rho, \tau)}$ and $N = \ensuremath{(\ensuremath{\mathcal{C}}', \otimes', I', \alpha', \lambda', \rho',
	\tau')}$ be symmetric monoidal categories.
\index{symmetric monoidal functor}
A \textbf{lax symmetric monoidal functor} $F: M \to N$ consists of
\begin{itemize}
\item a functor $F : \ensuremath{\mathcal{C}} \to \ensuremath{\mathcal{C}}'$,
\item morphisms $F_2 : (F A) \otimes' (F B) \to F(A \otimes B)$, natural in
$A,B \in \ensuremath{\mathcal{C}}$,
\item a morphism $F_0 : I' \to F I$ in $\ensuremath{\mathcal{C}}'$,
\end{itemize}
such that the following diagrams commute:
\begin{equation}
\label{eqn:symm_mon_fctr_assoc}
\xymatrix{
FA \otimes' (FB \otimes' FC) \ar[r]^{\alpha'} \ar[d]_{1 \otimes' F_2}
& (FA \otimes' FB) \otimes' FC \ar[d]^{F_2 \otimes' 1} \\
FA \otimes' (F(B \otimes C)) \ar[d]_{F_2}
& F(A \otimes B) \otimes' FC \ar[d]^{F_2} \\
F(A \otimes (B \otimes C)) \ar[r]^{F\alpha}
& F((A \otimes B) \otimes C)
}
\end{equation}
\begin{equation}
\label{eqn:symm_mon_fctr_unit}
\xymatrix{
(FB) \otimes' I' \ar[r]^{\rho'} \ar[d]_{1 \otimes' F_0}FB
& F B \\
(FB) \otimes' (FI) \ar[r]^{F_2}
& F(B \otimes I) \ar[u]_{F\rho}
}
\hskip 2em
\xymatrix{
I' \otimes' (FB) \ar[r]^{\lambda'}
& FB \\
(FI) \otimes' (FB) \ar[r]^{F_2} \ar[u]^{F_0 \otimes' 1}
& F(I \otimes B) \ar[u]_{F\lambda}
}
\end{equation}
\begin{equation}
\label{eqn:symm_mon_fctr_tau}
\xymatrix{
(FA)\otimes'(FB) \ar[r]^{\tau'} \ar[d]_{F_2}
& (FB) \otimes' (FA) \ar[d]^{F_2} \\
F(A \otimes B) \ar[r]^{F\tau}
& F(B \otimes A).
}
\end{equation}
$F$ is said to be \textbf{weak} when $F_0, F_2$ are isomorphisms, and
\textbf{strict} when $F_0, F_2$ are identities.
\index{lax!symmetric monoidal functor}
\index{weak!symmetric monoidal functor}
\index{strict!symmetric monoidal functor}

\label{lem:mon_fctr_coherence}
\index{coherence!for monoidal functors}
Let $M, N$ be monoidal categories, and $F : M \to N$ be a weak monoidal
functor.
For every $n \in \natural$ and every strongly regular $\Phi$-tree $v$ of arity
$n$, there is a unique map $F_v : v_N(F A_1, \dots, F A_n) \to Fv_M(A_1, \dots,
A_n)$ natural in $A_1, \dots, A_n \in M$ and formed by taking composites and
tensors of $F_0$ and $F_2$, such that the diagram
\[

	\xymatrix{
		v_N(F A_1, \dots F A_n) \ar[r]^-{F_{v}} \ar[d]_-{{\mbox{\upshape{can}}}_N}
		& Fv_M(A_1, \dots, A_n) \ar[d]^-{F{\mbox{\upshape{can}}}_M} \\
		w_N(F A_1, \dots F A_n) \ar[r]^-{F_{w}}
		& F(w)_M(A_1, \dots, A_n)
	}

\]
commutes for all $n \in \natural$, all $v, w \in ({\ensuremath{F_{\rm pl}}} \Phi)_n$, and all $A_1,
\dots, A_n \in \ensuremath{\mathcal{M}}$.

\label{thm:smcf_coherence}
\index{coherence!for symmetric monoidal functors}
Let $M,N$ be symmetric monoidal categories, and $F:M \to N$ be a weak symmetric monoidal functor.
Let $\sigma\cdot v$ be an $n$-ary\ permuted $\Phi$-tree.
Then there is a unique natural transformation
\[
\xymatrix{
	M^n \ar[r]^{F^n} \ar[d]_{(\sigma\cdot v)_M}
		\drtwocell\omit{^*{!(1,-1)\object{F_{\sigma\cdot v}}}}
	& N^n \ar[d]^{(\sigma\cdot v)_N} \\
	M \ar[r]_F & N
}
\]
formed by composing tensor products of $F_2$ and $F_0$, possibly with their
arguments permuted.
Furthermore, if $\rho\cdot w$ is another permuted $\Phi$-tree, then the diagram
\[

	\xymatrix{
		(\sigma\cdot v)_N(F A_1, \dots F A_n) \ar[r]^-{F_{\sigma\cdot v}} \ar[d]_-{{\mbox{\upshape{can}}}_N}
		& F(\sigma \cdot v)_M(A_1, \dots, A_n) \ar[d]^-{F{\mbox{\upshape{can}}}_M} \\
		(\rho \cdot w)_N(F A_1, \dots F A_n) \ar[r]^-{F_{\rho \cdot w}}
		& F(\rho\cdot w)_M(A_1, \dots, A_n)
	}

\]
commutes.

A (directed) \textbf{multigraph} consists of
\index{multigraph}
\begin{enumerate}
\item a set of \textbf{vertices} $V$,
\item for each $n \in \natural$ and each sequence $v_1, v_2, \dots,
v_n, w$ of vertices, a set $E(v_1, \dots, v_n; w)$ of \textbf{funnels from
$v_1, \dots, v_n$ to $w$}. 
\index{funnel}
\end{enumerate}

\index{multigraph!enriched}
Let \ensuremath{\mathcal{V}}\ be a category.
A \textbf{\ensuremath{\mathcal{V}}-multigraph} $M = (V,E)$ consists of
\begin{enumerate}
\item a set $V$ of \textbf{vertices},
\item for each $n \in \natural$ and each finite sequence $v_1, v_2 \dots v_n, w$
of vertices, an object of \ensuremath{\mathcal{V}}\ called $E(v_1, \dots, v_n; w)$ of
\textbf{funnels from $v_1, \dots, v_n$ to $w$}. 
\end{enumerate}

Let $M_1 = (V_1, E_1)$ and $M_2 = (V_2, E_2)$ be \ensuremath{\mathcal{V}}-multigraphs.
A \textbf{morphism of \ensuremath{\mathcal{V}}-multigraphs} $f: M_1 \to M_2$ is
\index{morphism!of enriched multigraphs}
\begin{enumerate}
\item a function $f_V : V_1 \to V_2$,
\item for each $n \in \natural$ and each finite sequence $v_1, v_2 \dots v_n,
w$ of vertices in $M_1$, an arrow $E_1(v_1, \dots, v_n; w)
	\to E_2(f_V(v_1), \dots, f_V(v_n); f_V(w))$ in \ensuremath{\mathcal{V}}.
\end{enumerate}

Let $M$ be the multicategory generated by
\[
\xymatrix{0 \ar[r]^f & 1 \ar[r]^g & 2}
\]
Then a weak algebra for $M$ in \ensuremath{\mbox{\upshape{\textbf{Cat}}}}\ with respect to this generating set
consists of a diagram
\[
\xymatrix{\hat 0 \ar[r]^{\hat f} & \hat 1 \ar[r]^{\hat g} & \hat 2}
\]
in \ensuremath{\mbox{\upshape{\textbf{Cat}}}}, whereas an unbiased weak $M$-algebra is a diagram
\[
\xymatrix{
\hat 0 \ar[dr]_{\hat f} \ar[rr]^{\widehat{gf}} \rrlowertwocell\omit{<3>\sim}
\ar@(ul,dl)[]_{\widehat{I_0}}
& & \hat 2 \ar@(ur,dr)[]^{\widehat{I_2}} \\
& \hat 1 \ar[ur]_{\hat g} \ar@(dl,dr)[]_{\widehat{I_1}}
}
\]
where $\widehat{I_0}, \widehat{I_1}$ and $\widehat{I_2}$ are trivial monads.

\index{strictification}
Let $P$, $Q$, $h$, $A$, $\iota$ be as above. The \textbf{strictification of
$A$}, written \ensuremath{\mbox{\upshape{\textbf{st}}}}(\ensuremath{A}), is given by the bijective-on-objects/full and
faithful factorization of $h(\iota \circ 1)$ in $\ensuremath{\mbox{\upshape{\textbf{Cat}}}}$:
\[
\xymatrix{
	P\circ A \ar[r]^{\iota \circ 1} \ar@{->>}[dr] & Q \circ A \ar[r]^h & A. \\
	& \ensuremath{\mbox{\upshape{\textbf{st}}}}(\ensuremath{A}) \ar@{(>->}[ur]
}
\]

It is clear that the action we have defined is strict and associative on
objects and that $1_P$ acts as a unit: we must show that the action on arrows
is associative.
Let $f_i^j:(p_i^j, a_{i\bullet}^j) \to (q_i^j, b_{i\bullet}^j)$, $\sigma \in Q_n$, and
$\tau_i \in Q_{k_i}$ for $j = 1, \dots, k_i$ and $i = 1,\dots,n$.
We wish to show that $h'(\sigma\circ(\tau_\bullet), f_\bullet^\bullet) = h'(\sigma,
h'(\tau_1, f_1^\bullet), \dots, h'(\tau_n, f_n^\bullet))$.

The LHS is
\[
\begin{array}{rcl}
h(\sigma\circ(\tau_\bullet)\circ(p_\bullet^\bullet), a_\bullet^\bullet)&

  \mathop{\stackrel{\scriptstyle{\delta_{\sigma\circ(\tau_i)\circ(p_\bullet^\bullet)}^{-1}}}{\longrightarrow}}
&
h(\sigma\circ(\tau_\bullet), h(p_1^1, a_{1\bullet}^1), \dots, h(p_n^{k_n},
a_{n\bullet}^{k_n}))\\
	&
  \mathop{\stackrel{\scriptstyle{h(\sigma\circ(\tau_\bullet), f_\bullet^\bullet)}}{\longrightarrow}}

&h(\sigma\circ(\tau_\bullet), h(q_1^1, b_{1\bullet}^1), \dots, h(q_n^{k'_n},
b_{n\bullet}^{k'_n}))\\
	&
  \mathop{\stackrel{\scriptstyle{\delta_{\sigma\circ(\tau_\bullet)\circ(q_\bullet^\bullet)}}}{\longrightarrow}}

&h(\sigma\circ(\tau_\bullet)\circ(q_\bullet^\bullet), b_\bullet^\bullet).
\end{array}
\]

The RHS is 
\[
\begin{array}{rcl}
h(\sigma\circ(\tau_\bullet)\circ(p_\bullet^\bullet), a_\bullet^\bullet)&

  \mathop{\stackrel{\scriptstyle{\delta_{\sigma\circ(\tau_i\circ(p_\bullet^\bullet))}^{-1}}}{\longrightarrow}}
&
h(\sigma, h(\tau_1\circ(p_1^\bullet), a_{1\bullet}^\bullet), \dots,
		h(\tau_n\circ(p_n^\bullet), a_{n\bullet}^\bullet)) \\
	&
  \mathop{\stackrel{\scriptstyle{h(\sigma, h'(\tau_\bullet, f_\bullet^\bullet))}}{\longrightarrow}}

&h(\sigma, h(\tau_1\circ(q_1^\bullet), b_{1\bullet}^\bullet), \dots,
		h(\tau_n\circ(q_n^\bullet), b_{n\bullet}^\bullet))\\
	&
  \mathop{\stackrel{\scriptstyle{\delta_{\sigma\circ(\tau_i\circ(p_\bullet^\bullet))}}}{\longrightarrow}}

&h(\sigma\circ(\tau_\bullet)\circ(q_\bullet^\bullet), b_\bullet^\bullet),
\end{array}
\]
where each $h'(\tau_i, f_i^\bullet)$ is
\[
\begin{array}{rcl}
h(\tau_i\circ(p_i^\bullet),a_i^\bullet))
	&
  \mathop{\stackrel{\scriptstyle{\delta_{\tau_i\circ(p_i^\bullet)}^{-1}}}{\longrightarrow}}

& h(\tau_i, h(p_i^1, a_{i\bullet}^1), \dots, h(p_i^{k_i}, a_{i\bullet}^{k_i}))\\
	&
  \mathop{\stackrel{\scriptstyle{h(\tau_i, f_i^\bullet)}}{\longrightarrow}}

& h(\tau_i, h(q_i^1, b_{i\bullet}^1), \dots, h(q_i^{k_i}, b_{i\bullet}^{k_i}))\\
	&
  \mathop{\stackrel{\scriptstyle{\delta_{\tau_i\circ(p_i^\bullet)}}}{\longrightarrow}}

&h(\tau_i\circ(q_i^\bullet),b_i^\bullet).
\end{array}
\]

So the equation holds if the following diagram commutes:

\[
\xymatrix @+10pt {

& h(\sigma\circ(\tau_\bullet)\circ(p_\bullet^\bullet), a_\bullet^\bullet)
	\ar[dl]_{\delta_{\sigma\circ(\tau_i)\circ(p_\bullet^\bullet)}^{-1}}
	\ar[dr]^{\delta_{\sigma\circ(\tau_i\circ(p_\bullet^\bullet))}^{-1}}
	\ar[d]|{\delta_{\sigma\circ(\tau_\bullet)\circ(p_\bullet^\bullet)}^{-1}} \\

h(\sigma\circ(\tau_\bullet), h(p_\bullet^\bullet, a_\bullet^\bullet))
	\ar[d]|{h(\sigma\circ(\tau_\bullet), f_\bullet^\bullet)}
& h(\sigma, h(\tau_\bullet\circ(p_\bullet^\bullet),a_\bullet^\bullet))
	\ar[l]^{\delta_{\sigma\circ(\tau_\bullet)}}
	\ar[d]|{h(\sigma, h(\tau_i, f_i^\bullet))}

	\ar @{} [dl]|*+[o][F-]{1}
	\ar @{} [dr]|*+[o][F-]{2}
& h(\sigma\circ(\tau_\bullet), h(p_\bullet^\bullet, a_\bullet^\bullet))
	\ar[l]^{h(\sigma, \delta_{\tau_\bullet\circ(p_\bullet^\bullet)}^{-1})}
	\ar[d]|{h(\sigma, h'(\tau_\bullet, f_\bullet^\bullet))}\\

h(\sigma\circ(\tau_\bullet), h(q_\bullet^\bullet, b_\bullet^\bullet))
	\ar[dr]_{\delta_{\sigma\circ(\tau_\bullet)\circ(q_\bullet^\bullet)}}
& h(\sigma, h(\tau_\bullet\circ(q_\bullet^\bullet), b_\bullet^\bullet))
	\ar[d]|{\delta_{\sigma\circ(\tau_\bullet\circ(q_\bullet^\bullet))}}
	\ar[l]^{\delta_{\sigma\circ(\tau_\bullet)}}
	\ar[r]_{h(\sigma, \delta_{\tau_i\circ(p_i^\bullet)})}
& h(\sigma, h(\tau_\bullet\circ(q_\bullet^\bullet), b_\bullet^\bullet))
	\ar[dl]^{\delta_{\sigma\circ(\tau_\bullet\circ(q_\bullet^\bullet))}}\\

&h(\sigma\circ(\tau_\bullet)\circ(q_\bullet^\bullet), b_\bullet^\bullet)\\
}
\]
The triangles all commute because all $\delta$s are images of arrows in $Q$,
and there is at most one 2-cell between any two 1-cells in $Q$. \ensuremath{\xymatrix{*+[o][F-]{2}}}
commutes by the definition of $h'(\tau_i, f_i^\bullet)$, and \ensuremath{\xymatrix{*+[o][F-]{1}}}
commutes by naturality of $\delta$.

